import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        orderInfoDetail: {
            marginLeft: theme.spacing(2)
        },
        paid: {
            color: '#1e88e5',
        },
        void: {
            color: '#7b7b7b',
        },
        due: {
            color: '#d23734',
        },
        detailContainer: {
            width: '100%',
            maxWidth: '100%',
            marginTop: theme.spacing(1)
        },
        contentBody: {
            marginTop: theme.spacing(2),
            marginBottom: theme.spacing(2),
            paddingLeft: theme.spacing(2)
        },
        title: {
            fontWeight: 'bold',
            padding: theme.spacing(2)
        },
        textWrapper: {
            wordWrap: 'break-word'
        },
        right: {
            textAlign: 'right'
        },
        dividerItem: {
            marginLeft: theme.spacing(2)
        },
        loading: {
            marginTop: theme.spacing(10)
        },
        paymentMethodInfo: {
            marginTop: theme.spacing(1),
            marginLeft: theme.spacing(2)
        },
        titlePayment: {
            paddingLeft: 0
        }
    };
    fire('material_styles_order_order_detail_style', {theme, style});
    return style;
};

export default styles;



