import RestAbstract from "./RestAbstract";
import DataResourceFactory from "../../../framework/factory/DataResourceFactory";

export class RestGiftcard extends RestAbstract {
    static className = 'RestGiftcard';

    apply_giftcode = "/V1/webpos/giftcard/apply";
    reload_giftcodes = "/V1/webpos/giftcard/get_giftcard_by_customer";

    /**
     * submit coupon code
     *
     * @param params
     *
     * @return promise
     */
    applyGiftcode(params) {
        let url = this.getBaseUrl() + this.apply_giftcode;
        return this.post(url, params);
    }

    /**
     * get list giftcodes by customer
     *
     * @param customer_id
     * @returns {Promise<any>}
     */
    reloadGiftCodes(customer_id){
        let url = this.getBaseUrl()+this.reload_giftcodes;
        if(customer_id) {
            url += '?customer_id=' + customer_id ;
        }
        return this.get(url);
    }
}

/**
 * @type {RestGiftcard}
 */
export default DataResourceFactory.get(RestGiftcard);



