import React, {Fragment} from 'react';
import CoreComponent from "../../../../framework/component/CoreComponent";
import ComponentFactory from "../../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../../framework/container/CoreContainer";
import ContainerFactory from "../../../../framework/factory/ContainerFactory";
import {Divider, ListItem, ListItemText, withStyles} from "@material-ui/core";
import CustomerStyle from "../../../style/material-styles/customer/customer-list/CustomerStyle";

export class CustomerComponent extends CoreComponent {
    static className = 'CustomerComponent';

    /**
     * Get customer name
     *
     * @param {object} customer
     * @return {string}
     */
    getCustomerName(customer) {
        return customer.id ? customer.firstname + " " + customer.lastname : "";
    }

    /**
     * Get customer telephone
     *
     * @param {object} customer
     * @return {string}
     */
    getCustomerTelephone(customer) {
        return customer.id && customer.telephone ? customer.telephone : "";
    }

    /**
     * render template
     *
     * @returns {*}
     */
    template() {
        let {customer} = this.props;
        return (
            <Fragment>
                <ListItem onClick={() => this.props.selectCustomer(customer)}>
                    <ListItemText
                        primary={this.getCustomerName(customer)}
                        secondary={this.getCustomerTelephone(customer)}
                    />
                </ListItem>
                <Divider variant="middle" component="li" />
            </Fragment>
        );
    }
}

/**
 *
 * @type {CustomerComponent}
 */
const component = withStyles(CustomerStyle)(ComponentFactory.get(CustomerComponent));

export class CustomerContainer extends CoreContainer{
    static className = 'CustomerContainer';
    
}

/**
 *
 * @type {CustomerContainer}
 */
const container = ContainerFactory.get(CustomerContainer);
export default container.getConnect(component);



