import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        checkoutButton: {
            height: '100%',
            fontSize: 20,
            fontWeight: 'bold'
        },
        wrapperCheckoutButton: {
            top: 'auto',
            height: theme.spacing(7),
            bottom: 0
        },
    };
    fire('material_styles_payment_checkout_button', {theme, style});
    return style;
};

export default styles;


