import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        wrapperCartSummary: {
            top: 'auto',
            height: theme.spacing(7),
            bottom: 0
        },
        cartTotalButton: {
            height: '100%',
            fontSize: 20,
            fontWeight: 'bold'
        },
        root: {
            flexGrow: 1,
        },
    };
    fire('material_styles_cart_cart_summary_style', {theme, style});
    return style;
};

export default styles;



