import RestAbstract from "./RestAbstract";
import DataResourceFactory from "../../../framework/factory/DataResourceFactory";

export class RestPerformance extends RestAbstract {
    static className = 'RestPerformance';

    save_log_api = "/V1/webpos/performance";
    /**
     * Sync saved data to server
     *
     * @param params
     *
     * @return promise
     */
    saveLog(params) {
        let url = this.getBaseUrl() + this.save_log_api;
        return this.post(url, params);
    }
}

/**
 * @type {RestPerformance}
 */
export default DataResourceFactory.get(RestPerformance);




