import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestQuote from "./rest/RestQuote";
import GraphqlQuote from "./graphql/GraphqlQuote";

export default class OmcQuote extends OmcAbstract {
    static className = 'OmcQuote';

    apiResources = {
        [ApiResourceConstant.REST]: RestQuote,
        [ApiResourceConstant.GRAPHQL]: GraphqlQuote,
    };

    /**
     * submit coupon code
     *
     * @param object
     *
     * @return promise
     */
    submitCouponCode(params) {
        return this.getRestResource().submitCouponCode(params);
    }
}




