import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        root: {
            width: '100%',
            backgroundColor: theme.palette.background.paper
        },
        menuButton: {
            marginRight: theme.spacing(0),
        }
    };
    fire('material_styles_catalog_product_list_style', {theme, style});
    return style;
};

export default styles;



