import RestAbstract from "./RestAbstract";
import DataResourceFactory from "../../../framework/factory/DataResourceFactory";

export class RestQuote extends RestAbstract {
    static className = 'RestQuote';

    submit_coupon_code = "/V1/webpos/checkout/checkPromotion";

    /**
     * submit coupon code
     *
     * @param object
     *
     * @return promise
     */
    submitCouponCode(params) {
        let url = this.getBaseUrl() + this.submit_coupon_code;
        return this.post(url, params);
    }
}

/**
 * @type {RestQuote}
 */
export default DataResourceFactory.get(RestQuote);



