import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        wrapperSearch: {
            backgroundColor: 'white'
        },
        searchForm: {
            width: '100%'
        }
    };
    fire('material_styles_catalog_search_form_style', {theme, style});
    return style;
};

export default styles;



