import EpicFactory from "../../../../../framework/factory/EpicFactory";
import LogConstant from "../../../../constant/log/LogConstant";
import LogService from "../../../../../service/log/LogService";
import CheckoutConstant from "../../../../constant/CheckoutConstant";
import UserService from "../../../../../service/user/UserService";
import {Observable} from "rxjs";
import ExceptionLogConstant from "../../../../constant/log/ExceptionLogConstant";
import PosService from "../../../../../service/PosService";

function LogCheckoutProcessSinglePaymentErrorEpic(action$, store) {
    return action$.ofType(CheckoutConstant.CHECKOUT_PROCESS_SINGLE_PAYMENT_ERROR)
        .mergeMap((action) => {
            let {result, payment} = action;
            let quote = store.getState().core.checkout.quote;
            let log = {
                [LogConstant.LOG_TYPE]: LogConstant.EXCEPTION,
                [LogConstant.LOG_FLOW]: LogConstant.FLOW_PLACE_ORDER,
                [LogConstant.BUSINESS_FLOW]: LogConstant.BUSINESS_FLOW_PROCESS_PAYMENT,
                [LogConstant.USER_TYPE]: LogConstant.USER_TYPE_STAFF,
                [LogConstant.USER_EMAIL]: UserService.getStaffEmail(),
                [LogConstant.USER_NAME]: UserService.getStaffName(),
                [LogConstant.LOG_MESSAGE]: "Process payment (" + payment.method + ") #" + payment.increment_id
                    + " failed - Quote #" + quote.id + " - Pos: " + PosService.getCurrentPosName(),
                [ExceptionLogConstant.EXCEPTION_LEVEL]: ExceptionLogConstant.ERROR,
                [ExceptionLogConstant.EXCEPTION_MESSAGE]: result.message,
                [ExceptionLogConstant.STACK_TRACE]: 'N/A',
                [ExceptionLogConstant.ADDITIONAL_INFO]: {
                    payment: LogService.cloneAndFilterPaymentData(payment),
                    result: result
                }
            };
            LogService.saveLog(log);
            return Observable.empty();
        });
}

LogCheckoutProcessSinglePaymentErrorEpic.className = 'LogCheckoutProcessSinglePaymentErrorEpic';

export default EpicFactory.get(LogCheckoutProcessSinglePaymentErrorEpic);



