import {fire} from "../../../../../event-bus";

const styles = theme => {
    let style = {
        checkboxWrapper: {
            marginTop: theme.spacing(2),
        },
    };
    fire('material_styles_customer_fields_customer_checkbox_style', {theme, style});
    return style;
};

export default styles;



