import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        cartItemThumbnail: {
            float: 'left',
            display: 'inline-block',
            wordWrap: 'break-word',
            width: theme.spacing(3)
        },
        cartItemThumbnailWrapper: {
            width: theme.spacing(9),
            paddingRight: theme.spacing(1),
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center'
        },
        cartItemName: {
            width: theme.spacing(20),
            paddingLeft: theme.spacing(1),
            '& > *': {
                wordWrap: 'break-word'
            },
        },
        cardItemRoot: {
            width: '100%'
        },
        unitPrice: {
            display: 'block',
            width: '100%'
        },
        totalPrice: {
            display: 'block',
            width: '100%',
            fontWeight: 'bold'
        },
        originalPrice: {
            display: 'block',
            width: '100%',
            textDecoration: 'line-through'
        },
    };
    fire('material_styles_cart_cart_item_style', {theme, style});
    return style;
};

export default styles;



