import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestGiftcard from "./rest/RestGiftcard";
import GraphqlGiftcard from "./graphql/GraphqlGiftcard";

export default class OmcGiftcard extends OmcAbstract {
    static className = 'OmcGiftcard';

    apiResources = {
        [ApiResourceConstant.REST]: RestGiftcard,
        [ApiResourceConstant.GRAPHQL]: GraphqlGiftcard
    };

    /**
     * submit coupon code
     *
     * @param params
     *
     * @return promise
     */
    applyGiftcode(params) {
        return this.getRestResource().applyGiftcode(params);
    }

    /**
     * get list giftcodes by customer
     *
     * @param customer_id
     * @returns {Promise<any>}
     */
    reloadGiftCodes(customer_id){
        return this.getRestResource().reloadGiftCodes(customer_id);
    }
}




