import React, {Fragment} from 'react';
import CoreComponent from "../../../../framework/component/CoreComponent";
import ComponentFactory from "../../../../framework/factory/ComponentFactory";
import ContainerFactory from "../../../../framework/factory/ContainerFactory";
import CoreContainer from "../../../../framework/container/CoreContainer";
import CurrencyHelper from "../../../../helper/CurrencyHelper";
import NumberHelper from "../../../../helper/NumberHelper";
import {Backdrop, CircularProgress, ListItem, ListItemText, withStyles} from "@material-ui/core";
import {CustomDiscountService} from "../../../../service/checkout/quote/CustomDiscountService";
import PaymentHelper from "../../../../helper/PaymentHelper";
import CartTotalsDiscountStyle from "../../../style/material-styles/cart/totals/CartTotalsDiscountStyle";
import CartTotalsStyle from "../../../style/material-styles/cart/CartTotalsStyle";

export class CartTotalsDiscountComponent extends CoreComponent {
    static className = 'CartTotalsDiscountComponent';

    /**
     * Get discount element
     * @param quote
     * @param total
     * @param hasPaidOrWaitingGatewayPayment
     * @returns {JSX.Element}
     */
    getDiscountElement(quote, total, hasPaidOrWaitingGatewayPayment) {
        let discountAmount = total.value;
        let displayValue = CurrencyHelper.format(discountAmount);
        let title = total.title;
        let {os_pos_custom_discount_type, os_pos_custom_discount_amount} = quote;
        if (os_pos_custom_discount_type && displayValue.length > 0) {
            switch (os_pos_custom_discount_type) {
                case CustomDiscountService.DISCOUNT_TYPE_PERCENT:
                    title = this.props.t(
                        'Custom Discount ({{max}})',
                        {
                            max: NumberHelper.formatDisplayGroupAndDecimalSeparator(os_pos_custom_discount_amount) + "%"
                        }
                    );
                    break;
                case CustomDiscountService.DISCOUNT_TYPE_FIXED:
                    title = this.props.t('Custom Discount');
                    break;
                default:
                    break
            }
        }
        return (
            <ListItem className={total.code + ' ' + this.props.classes.cartTotalsItem}>
                <ListItemText primary={title + ': ' + displayValue}/>
            </ListItem>
        );
    }

    /**
     * Render tax total
     *
     * @return {*}
     */
    template() {
        let {total, quote, hasPaidOrWaitingGatewayPayment} = this.props;
        return (
            <Fragment key={total.code}>
                {this.getDiscountElement(quote, total, hasPaidOrWaitingGatewayPayment)}
                <Backdrop open={!!quote.checking_promotion} className={this.props.classes.backdrop}>
                    <CircularProgress/>
                </Backdrop>
            </Fragment>
        );
    }
}

export class CartTotalsDiscountContainer extends CoreContainer {
    static className = 'CartTotalsDiscountContainer';

    /**
     *
     * @param state
     * @return {{quote: *}}
     */
    static mapState(state) {
        const {quote} = state.core.checkout;
        const hasPaidOrWaitingGatewayPayment = PaymentHelper.hasPaidOrWaitingGatewayPayment(quote.payments);
        return {
            hasPaidOrWaitingGatewayPayment
        }
    }
}

/**
 *
 * @type {CartTotalsDiscountContainer}
 */
const container = ContainerFactory.get(CartTotalsDiscountContainer);
export default container.getConnect(
    withStyles(
        (theme) => ({
            ...CartTotalsDiscountStyle(theme),
            ...CartTotalsStyle(theme)
        })
    )(ComponentFactory.get(CartTotalsDiscountComponent))
);



