import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        completeOrderWrapper: {
            marginTop: theme.spacing(12)
        }
    };
    fire('material_styles_payment_complete_order', {theme, style});
    return style;
};

export default styles;


