import React from 'react';
import PropTypes from 'prop-types';
import {CoreComponent} from '../../../../framework/component/index'
import ComponentFactory from "../../../../framework/factory/ComponentFactory";
import {FormControl, FormControlLabel, Switch, withStyles} from "@material-ui/core";
import CustomerCheckboxStyle from "../../../style/material-styles/customer/fields/CustomerCheckboxStyle";

export class CustomerCheckboxComponent extends CoreComponent {
    static className = 'CustomerCheckboxComponent';
    input;

    /**
     * constructor
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {
            defaultValue: props.IsCheck
        }
    }

    /**
     * set input
     * @param input
     */
    setInput(input) {
        this.input = input;
    }

    /**
     * validate
     */
    validate() {

    }

    /**
     * onchange
     */
    onChange() {
        if (this.props.onSelect) {
            let value = this.input.checked ? 1 : 0;
            this.props.onSelect(this.props.Code, value);
        }
    }

    template() {
        let { Label, Disabled, classes } = this.props;
        return (
            <FormControl fullWidth className={classes.checkboxWrapper}>
                <FormControlLabel
                    control={
                        <Switch
                            defaultChecked={!!this.state.defaultValue}
                            onChange={this.onChange.bind(this)}
                            color="primary"
                            disabled={Disabled}
                            inputRef={this.setInput.bind(this)}
                        />
                    }
                    label={ Label }
                />
            </FormControl>
        );
    }
}

CustomerCheckboxComponent.propTypes = {
    Label: PropTypes.string,
    OneRow: PropTypes.bool,
    onSelect: PropTypes.func,
    Disabled: PropTypes.bool
};

/**
 * CustomerCheckboxComponent
 */
export default withStyles(CustomerCheckboxStyle)(ComponentFactory.get(CustomerCheckboxComponent));



