import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        editPaymentWrapper: {
            marginTop: theme.spacing(12)
        },
        actionButton: {
            '& > *': {
                margin: theme.spacing(2),
                textTransform: 'none'
            },
        },
        paymentInfo: {
            '& > *': {
                margin: theme.spacing(2),
            },
        },
        paymentIcon: {
            fontSize: theme.spacing(10),
            align:"center",
            color: theme.palette.primary.main
        },
        referenceWrapper: {
            '& > *': {
                margin: theme.spacing(1),
                width: '25ch',
            },
        },
    };
    fire('material_styles_payment_edit_payment', {theme, style});
    return style;
};

export default styles;


