import {fire} from "../../../../../event-bus";

const styles = theme => {
    let style = {
        contentWrapper: {
            marginTop: theme.spacing(20),
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
        },
        qtyInput: {
            '& input': {
                textAlign: 'center',
                fontSize: theme.spacing(5)
            }
        }
    };
    fire('material_styles_cart_item_edit_cart_item_style', {theme, style});
    return style;
};

export default styles;



