import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestShipping from "./rest/RestShipping";
import GraphqlShipping from "./graphql/GraphqlShipping";

export default class OmcShipping extends OmcAbstract {
    static className = 'OmcShipping';

    apiResources = {
        [ApiResourceConstant.REST]: RestShipping,
        [ApiResourceConstant.GRAPHQL]: GraphqlShipping,
    };
}


