import {fire} from "../../../../../event-bus";

const styles = theme => {
    let style = {
        popper: {
            zIndex: theme.zIndex.tooltip,
            maxWidth: '95%',
        },
        paper: {
            maxHeight: theme.spacing(35),
            overflow: 'auto'
        }
    };
    fire('material_styles_customer_address_google_suggest_style', {theme, style});
    return style;
};

export default styles;



