import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        toggleMenuButton: {
            zIndex: 1110,
            color: 'white',
            padding: 0,
            position: 'fixed'
        },
        menuTitle: {
            paddingTop: theme.spacing(2),
            paddingLeft: theme.spacing(2),
        },
        staffName: {
            fontWeight: 'bold'
        },
        drawerPaper: {
            width: theme.spacing(35),
            maxWidth: '80%',
        },
        list: {
            height: 'inherit',
            overflowY: 'auto'
        },
        menuItemIcon: {
            height: theme.spacing(4),
            width: theme.spacing(4)
        },
        menuFooter: {
            paddingLeft: theme.spacing(2),
            display: 'flex'
        },
        posVersion: {
            fontWeight: 'bold',
            paddingTop: theme.spacing(1),
        }
    };
    fire('material_styles_menu_menu', {theme, style});
    return style;
};

export default styles;


