import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestPayment from "./rest/RestPayment";
import GraphqlPayment from "./graphql/GraphqlPayment";

export default class OmcPayment extends OmcAbstract {
    static className = 'OmcPayment';

    apiResources = {
        [ApiResourceConstant.REST]: RestPayment,
        [ApiResourceConstant.GRAPHQL]: GraphqlPayment,
    };

    /**
     * get token stripe payment
     * @param payment
     * @param public_key
     * @returns {Promise}
     */
    getTokenStripePayment(payment, public_key) {
        return this.getRestResource().getTokenStripePayment(payment, public_key);
    }

    /**
     * stripe finish payment
     * @param token
     * @param amount
     * @returns {Promise.<any>}
     * @constructor
     */
    stripeFinishPayment(token, amount) {
        return this.getRestResource().stripeFinishPayment(token, amount);
    }

    /**
     * get token authorize.net
     * @param payment
     * @param api_login
     * @param client_id
     * @param is_sandbox
     * @returns {Promise.<any>}
     */
    getTokenAuthorizeNetPayment(payment, api_login, client_id, is_sandbox) {
        return this.getRestResource().getTokenAuthorizeNetPayment(payment, api_login, client_id, is_sandbox);
    }

    /**
     * authorize finish payment
     * @param token
     * @param amount
     * @returns {Promise.<any>}
     * @constructor
     */
    authorizeNetFinishPayment(token, amount) {
        return this.getRestResource().authorizeNetFinishPayment(token, amount);
    }

    /**
     *
     * @param request
     * @return {Promise<any>}
     */
    paypalDirectPayment(request) {
        return this.getRestResource().paypalDirectPayment(request);
    }

    /**
     *
     * @param payload
     * @return {Promise<any>}
     */
    paypalSendInvoice(payload) {
        return this.getRestResource().paypalSendInvoice(payload);
    }
}



