import RestAbstract from "./RestAbstract";
import DataResourceFactory from "../../../framework/factory/DataResourceFactory";

export class RestCategory extends RestAbstract {
    static className = 'RestCategory';

    get_list_api = "/V1/webpos/categories";
    get_deleted_api = "/V1/webpos/categories/deleted";
}

/**
 * @type {RestCategory}
 */
export default DataResourceFactory.get(RestCategory);



