import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        root: {
            flexGrow: 1,
        },
        backButton: {
            marginRight: theme.spacing(0),
        }
    };
    fire('material_styles_payment_payment_header', {theme, style});
    return style;
};

export default styles;



