import React, {Fragment} from 'react';
import CoreComponent from "../../../framework/component/CoreComponent";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CurrencyHelper from "../../../helper/CurrencyHelper";
import CoreContainer from "../../../framework/container/CoreContainer";
import QuoteAction from "../../action/checkout/QuoteAction";
import {bindActionCreators} from "redux";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import QuoteItemService from "../../../service/checkout/quote/ItemService";
import ProductImage from "../../style/images/product_placeholder.png";
import ProductList from "../catalog/ProductList";
import ProductTypeConstant from "../../constant/ProductTypeConstant";
import ListItem from "@material-ui/core/ListItem";
import Box from "@material-ui/core/Box";
import Avatar from "@material-ui/core/Avatar";
import ListItemText from "@material-ui/core/ListItemText";
import Divider from "@material-ui/core/Divider";
import CartItemStyle from "../../style/material-styles/cart/CartItemStyle";
import {withStyles} from "@material-ui/core";
import CheckoutAction from "../../action/CheckoutAction";
import Typography from "@material-ui/core/Typography";

export class CartItemComponent extends CoreComponent {
    static className = 'CartItemComponent';

    /**
     *
     */
    constructor(props) {
        super(props);
        const {item} = props;
        this.state = {
            item,
            decimalSymbol: CurrencyHelper.getDecimalSymbol()
        }
    }

    /**
     * Get product image to show in cart item
     *
     * @return {string}
     */
    getProductImage(product) {
        let productImage = product.image;
        if (!productImage) {
            productImage = ProductImage;
        }
        if (productImage.includes('http://') && window.location.href.includes('https://')) {
            productImage.replace('http://', 'https://')
        }
        return productImage;
    }

    /**
     * Handle click cart item
     */
    handleClickCartItem() {
        this.props.actions.showEditCartItemPage(this.props.item);
    }

    /**
     *  render template
     * @return {*}
     */
    template() {
        const {classes, quote, item} = this.props;
        let childItem = false;

        if (item.product_type === ProductTypeConstant.CONFIGURABLE) {
            childItem = QuoteItemService.getChildrenItems(quote, item)[0];
        }

        const realProduct = childItem ? childItem.product : item.product;
        return (
            <Fragment>
                <ListItem onClick={() => this.handleClickCartItem()} classes={{root: classes.cardItemRoot}}>
                    <Box className={classes.cartItemThumbnailWrapper} >
                        <Avatar src={this.getProductImage(realProduct)} />
                    </Box>
                    <ListItemText className={classes.cartItemName}
                        primary={item.name}
                        secondary={
                            <Fragment>
                                <Typography
                                    component="span"
                                    variant="body2"
                                    className={classes.unitPrice}
                                    color="textPrimary"
                                >
                                    {QuoteItemService.getItemPriceUnit(item, this.props.quote)}
                                    { ' (X' + item.qty + ')'}
                                </Typography>
                                <Typography
                                    component="span"
                                    variant="body2"
                                    className={classes.totalPrice}
                                    color="textPrimary"
                                >
                                    {QuoteItemService.getDisplayPrice(item, this.props.quote)}
                                </Typography>
                                {
                                    QuoteItemService.showOriginalPrice(item, this.props.quote) ?
                                        <Typography
                                            component="span"
                                            variant="body2"
                                            className={classes.originalPrice}
                                            color="textPrimary"
                                        >
                                            {QuoteItemService.getDisplayOriginalPrice(item, this.props.quote)}
                                        </Typography>
                                        : null
                                }
                            </Fragment>
                        }
                    />
                </ListItem>
                <Divider variant="inset" component="li"/>
            </Fragment>
        );
    }
}

/**
 *
 * @type {CartItemComponent}
 */
const component = ComponentFactory.get(CartItemComponent);

class CartItemContainer extends CoreContainer {
    static className = 'CartItemContainer';

    /**
     *
     * @param state
     * @return {{isDisableEdit: boolean}}
     */
    static mapState(state) {
        const {index, quote} = state.core.checkout;
        const checkoutCurrentPage = index.currentPage;
        return {
            quote,
            isDisableEdit: checkoutCurrentPage !== ProductList.className
        }
    }

    /**
     *
     * @param dispatch
     * @return {{actions: {setQuote, addProduct, addProductSuccess, addProductFail, removeCartItem, removeCartItemSuccess, removeCartItemFail, updateQtyCartItem, updateQtyCartItemSuccess, updateQtyCartItemFail, setPayments}|ActionCreator<any>|ActionCreatorsMapObject}}
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                ...bindActionCreators({...QuoteAction}, dispatch),
                showEditCartItemPage: (item) => dispatch(CheckoutAction.showEditCartItemPage(item))
            }
        }
    }
}

/**
 *
 * @type {CartItemContainer}
 */
const container = ContainerFactory.get(CartItemContainer);

export default container.getConnect(withStyles(CartItemStyle)(component));



