import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        backButton: {
            marginRight: theme.spacing(0),
        },
        list: {
            width: '100%',
            backgroundColor: theme.palette.background.paper,
            height: 'inherit',
            overflowY: 'auto'
        },
        searchForm: {
            width: '100%'
        },
        removeCustomerButton: {
            width: '95%',
            alignSelf: 'center',
            marginBottom: theme.spacing(1)
        }
    };
    fire('material_styles_customer_customer_list_style', {theme, style});
    return style;
};

export default styles;



