import React, {Fragment} from 'react';
import CoreComponent from '../../../framework/component/CoreComponent';
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import AppBar from "@material-ui/core/AppBar";
import Toolbar from "@material-ui/core/Toolbar";
import PaymentHeaderStyle from "../../style/material-styles/payment/PaymentHeader";
import {IconButton, withStyles} from "@material-ui/core";
import Container from "@material-ui/core/Container";
import Typography from "@material-ui/core/Typography";
import ArrowBack from "@material-ui/icons/ArrowBack";

export class PaymentHeaderComponent extends CoreComponent {
    static className = 'PaymentHeaderComponent';

    /**
     * Render template
     *
     * @returns {*}
     */
    template() {
        const {classes} = this.props;
        return (
            <Fragment>
                <Container>
                    <AppBar>
                        <Toolbar>
                            <IconButton edge="start"
                                        onClick={() => this.props.history.replace('/checkout/cart')}
                                        className={classes.backButton} color="inherit" aria-label="menu">
                                <ArrowBack />
                            </IconButton>
                            <Typography variant="h6" component="div">
                                {this.props.t('PAYMENT')}
                            </Typography>
                        </Toolbar>
                    </AppBar>
                    <Toolbar />
                </Container>
            </Fragment>
        );
    }
}

/**
 *  @type {PaymentHeaderComponent}
 */
const component = ComponentFactory.get(PaymentHeaderComponent);

class PaymentHeaderContainer extends CoreContainer {
    static className = 'PaymentHeaderContainer';

    /**
     *
     * @param state
     * @return {{quote: *}}
     */
    static mapState(state) {
        const {quote} = state.core.checkout;
        const {currentPage} = state.core.checkout.index;
        return {
            quote,
            currentPage
        }
    }
}

/**
 *
 * @type {PaymentHeaderContainer}
 */
const container = ContainerFactory.get(PaymentHeaderContainer);
export default container.withRouter(withStyles(PaymentHeaderStyle)(component));



