import CustomerConstant from '../../constant/CustomerConstant';
import LogoutPopupConstant from "../../constant/LogoutPopupConstant";

const initialState = {
    customer: null,
    showCustomerPopup: false,
    isNewCustomer: true
};

/**
 * Receive action from Customer Action
 *
 * @param state = {customers: []}
 * @param {object} action
 * @returns {*}
 */
const customerPopupReducer = function (state = JSON.parse(JSON.stringify(initialState)), action) {
    switch (action.type) {
        case CustomerConstant.OPEN_CUSTOMER_POPUP:
            return {
                ...state,
                customer: action.customer,
                showCustomerPopup: true,
                isNewCustomer: !action.customer
            };
        case CustomerConstant.CLOSE_CUSTOMER_POPUP:
            return {
                ...state,
                customer: null,
                showCustomerPopup: false
            };
        case LogoutPopupConstant.FINISH_LOGOUT_REQUESTING:
            return JSON.parse(JSON.stringify(initialState));
        default:
            return state
    }
};

export default customerPopupReducer;



