import React, {Fragment} from 'react';
import CoreComponent from "../../../framework/component/CoreComponent";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import {IconButton, withStyles} from "@material-ui/core";
import AddNewCustomerButtonStyle from "../../style/material-styles/customer/AddNewCustomerButtonStyle";
import AddIcon from '@material-ui/icons/Add';
import CustomerAction from "../../action/CustomerAction";

export class AddNewCustomerButtonComponent extends CoreComponent {
    static className = 'AddNewCustomerButtonComponent';

    /**
     * Handle Click Button
     */
    handleClickButton() {
        this.props.actions.openCustomerPopup();
    }

    /**
     * render template
     *
     * @returns {*}
     */
    template() {
        return (
            <Fragment>
                <IconButton aria-label="add new customer"
                            className={this.props.classes.addNewCustomerButton}
                            color={"inherit"}
                            onClick={() => this.handleClickButton()}
                >
                    <AddIcon fontSize={"large"}/>
                </IconButton>
            </Fragment>
        );
    }
}

/**
 *
 * @type {AddNewCustomerButtonComponent}
 */
const component = withStyles(AddNewCustomerButtonStyle)(ComponentFactory.get(AddNewCustomerButtonComponent));

export class AddNewCustomerButtonContainer extends CoreContainer{
    static className = 'AddNewCustomerButtonContainer';

    /**
     * @inheritDoc
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                openCustomerPopup: () => dispatch(CustomerAction.openCustomerPopup())
            }
        }
    }
}

/**
 *
 * @type {AddNewCustomerButtonContainer}
 */
const container = ContainerFactory.get(AddNewCustomerButtonContainer);
export default container.getConnect(component);



