import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        couponCodeInput: {
            width: '100%'
        },
        couponCodeButtonWrapper: {
            alignItems: 'center',
            display: 'flex'
        },
        couponCodeButton: {
            width: '100%',
            height: '100%'
        },
        couponWrapper: {
            marginTop: '50px',
            marginBottom: '50px'
        },
        backdrop: {
            zIndex: theme.zIndex.drawer + 1,
        }
    };
    fire('material_styles_coupon_coupon_code_form_style', {theme, style});
    return style;
};

export default styles;



