import React, {Fragment} from 'react';
import CoreComponent from "../../../framework/component/CoreComponent";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import Box from "@material-ui/core/Box";
import Button from '@material-ui/core/Button';
import TextField from "@material-ui/core/TextField";
import {Backdrop, CircularProgress, Grid} from "@material-ui/core";
import QuoteService from "../../../service/checkout/QuoteService";
import {fire} from "../../../event-bus";
import CouponTypeConstant from "../../../view/constant/salesrule/CouponTypeConstant";
import { toast } from 'react-toastify';
import i18n from "../../../config/i18n";
import {withStyles} from "@material-ui/core";
import CouponCodeFormStyle from "../../style/material-styles/coupon/CouponCodeFormStyle";
import QuoteAction from "../../../view/action/checkout/QuoteAction";
import CheckoutAction from "../../../view/action/CheckoutAction";
import ApiResponseConstant from "../../../view/constant/ApiResponseConstant";

export class CouponFormComponent extends CoreComponent {
    static className = 'CouponFormComponent';


    /**
     *   initial state
     */
    constructor(props) {
        super(props);
        this.state = {
            couponcode: '',
            message: '',
            couponCodeApplied: '',
            is_appling_coupon: false
        };
        this.checkPromotion = this.checkPromotion.bind(this);
        document.addEventListener('keydown', (event) => {
            const keyName = event.key;

            if (keyName === "Enter") {
                if (this.state.couponcode) {
                    this.submitCouponCode();
                }
            }
        });
    }

    /**
     *  will receive props reset state when not apply coupon
     *
     * @param nextProps
     * @return
     */
    componentWillReceiveProps(nextProps) {
        if (nextProps && nextProps.quote) {
            if (!nextProps.quote.coupon_code) {
                this.setState({
                    message: '',
                    is_appling_coupon: false,
                    couponcode: '',
                    couponCodeApplied: ''
                })
            } else {
                if (!this.state.couponCodeApplied) {
                    /* For reload page */
                    this.setState({
                        couponcode: nextProps.quote.coupon_code,
                        couponCodeApplied: nextProps.quote.coupon_code
                    }, () => this.submitCouponCode());
                }
            }

        }
    }

    /**
     * Set value for coupon form
     */
    componentDidMount() {
        if (this.props.quote.coupon_code) {
            this.setState(
                {
                    couponcode: this.props.quote.coupon_code,
                    couponCodeApplied: this.props.quote.coupon_code
                }
            )
            this.refInputCoupon.value = this.props.quote.coupon_code;
        }
    }

    /**
     * render template
     * @return {*}
     */
    template() {
        const {classes} = this.props;
        return (
            <Fragment>
                <Box sx={{ flexGrow: 1 }} className={classes.couponWrapper}>
                    <Grid container spacing={2}>
                        <Grid item xs={8}>
                            <TextField id="outlined-basic" onChange={(event) => this.couponCodeChange(event)}
                                       className={classes.couponCodeInput}
                                       style={{width: '100%'}}
                                       label="Coupon Code" variant="outlined"
                                       inputProps={{
                                           ref: this.setInputCoupon.bind(this),
                                           value: this.state.couponcode
                                       }}
                            />

                        </Grid>
                        <Grid item xs={4} className={classes.couponCodeButtonWrapper}>
                            {
                                !this.state.couponCodeApplied ?
                                    <Button variant="contained"
                                            className={classes.couponCodeButton}
                                            color="primary" onClick={() => this.submitCouponCode()}>
                                        {this.props.t('Apply')}
                                    </Button>
                                    : ''
                            }
                            {
                                this.state.couponCodeApplied ?
                                    <Button variant="contained" className={classes.couponCodeButton}
                                            onClick={() => this.removeCouponCode()}>
                                        {this.props.t('Remove')}
                                    </Button>
                                    : ''
                            }
                        </Grid>
                    </Grid>
                </Box>
                <Backdrop open={!!this.state.is_appling_coupon} className={this.props.classes.backdrop}>
                    <CircularProgress/>
                </Backdrop>
            </Fragment>
        );
    }

    submitCouponCode() {
        let couponCode = this.state.couponcode;
        if (!couponCode) {
            toast.error(
                i18n.translator.translate('Please enter a coupon code!'),
                {
                    className: 'wrapper-messages messages-warning',
                    autoClose: 2000
                }
            );
            return;
        }
        this.setState({messsge: '', is_appling_coupon: true});
        QuoteService.submitCouponCode(this.props.quote, couponCode).then(async rules => {
            let quote = this.props.quote;
            if (rules && rules.length) {
                fire('view_cart_discount_call_api_submit_coupon_code_after', {
                    quote: quote,
                    rules: rules
                });
                this.setState({is_appling_coupon: false});
                let couponRule = rules.find(rule => rule.coupon_type === CouponTypeConstant.COUPON_TYPE_SPECIFIC);
                if (couponRule && couponRule.rule_id) {
                    quote.coupon_code = couponCode;
                    this.setState({couponCodeApplied: this.state.couponcode});
                    quote.valid_salesrule = rules;
                    this.props.actions.addCouponCodeAfter(quote);
                    QuoteService.collectTotals(quote);
                    if (!quote.grand_total) {
                        await this.props.actions.setQuote(quote);
                        this.props.actions.checkoutToSelectPayments(quote);
                    } else {
                        this.props.actions.setQuote(quote);
                    }
                } else {
                    toast.error(
                        i18n.translator.translate('Invalid Coupon Code'),
                        {
                            className: 'wrapper-messages messages-warning',
                            autoClose: 2000
                        }
                    );
                }
            } else {
                this.setState({is_appling_coupon: false});
                toast.error(
                    i18n.translator.translate('Invalid Coupon Code'),
                    {
                        className: 'wrapper-messages messages-warning',
                        autoClose: 2000
                    }
                );
            }
            return rules;
        }).catch(error => {
                this.setState({is_appling_coupon: false});
                toast.error(
                    i18n.translator.translate(error.message),
                    {
                        className: 'wrapper-messages messages-warning',
                        autoClose: 2000
                    }
                );
            });
    }

    /**
     *  Change coupon code when type input field
     *
     * @return rules
     */
    couponCodeChange(e) {
        this.setState({couponcode: e.target.value});
        this.setState({message: ''});
    }


    setInputCoupon(element) {
        if (element) {
            this.refInputCoupon = element;
        }
    }

    /**
     *  Remove coupon code in quote
     *
     * @return rules
     */
    removeCouponCode() {
        let quote = this.props.quote;
        this.props.actions.removeCouponCode(quote);
        this.resetState();
        this.checkPromotion();
    }

    /**
     *  Reset State to default
     *
     * @return
     */
    resetState() {
        this.setState({
            message: '',
            is_appling_coupon: false,
            couponcode: '',
            couponCodeApplied: ''
        })
        if (this.refInputCoupon) {
            this.refInputCoupon.value = '';
        }
    }

    /**
     *
     * @returns {CartTotalsDiscountComponent}
     */
    checkPromotion() {
        let quote = this.props.quote;
        let configCheckPromotion = true;
        let hasCustomSale = quote.items.find(item => item.product.id < 0);
        if (hasCustomSale) {
            configCheckPromotion = false;
        }
        if (configCheckPromotion) {
            QuoteService.submitCouponCode(quote, "")
                .then(async rules => {
                    if (rules && rules.length) {
                        quote = this.props.quote;
                        let promotionRules = rules.filter(
                            rule => rule.coupon_type === CouponTypeConstant.COUPON_TYPE_NO_COUPON
                        );
                        if (promotionRules) {
                            quote.valid_salesrule = promotionRules;
                            QuoteService.collectTotals(quote);
                            if (!quote.grand_total && this.props.currentPage === 'PaymentComponent') {
                                await this.props.actions.setQuote(quote);
                                this.props.actions.checkoutToSelectPayments(quote);
                            } else {
                                this.props.actions.setQuote(quote);
                            }
                        }
                    }
                })
                .catch(error => {
                    if (
                        error.code === ApiResponseConstant.EXCEPTION_CODE_FORCE_CHANGE_POS
                        || error.code === ApiResponseConstant.EXCEPTION_CODE_FORCE_SIGN_OUT
                    ) {
                        // do something
                    }
                });
        }
        return this;
    }
}

/**
 *
 * @type {CouponFormComponent}
 */
const component = ComponentFactory.get(CouponFormComponent);

export class CouponFormContainer extends CoreContainer {
    static className = 'CouponFormContainer';

    /**
     *
     * @param state
     * @return {{quote: *}}
     */
    static mapState(state) {
        const {currentPage} = state.core.checkout.index;
        const {quote} = state.core.checkout;
        return {
            currentPage,
            quote
        }
    }


    /**
     *
     * @param dispatch
     * @return {{actions: {placeOrder, placeOrderResult, placeOrderError, checkoutToSelectPayments}|ActionCreator<any>|ActionCreatorsMapObject}}
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                removeCustomDiscount: (quote) => dispatch(QuoteAction.removeCustomDiscount(quote)),
                removeCouponCode: (quote) => dispatch(QuoteAction.removeCouponCode(quote)),
                addCouponCodeAfter: (quote) => dispatch(QuoteAction.addCouponCodeAfter(quote)),
                setQuote: (quote) => dispatch(QuoteAction.setQuote(quote)),
                checkoutToSelectPayments: (quote, initPayments) => dispatch(
                    CheckoutAction.checkoutToSelectPayments(quote, initPayments)
                ),
            }
        }
    }
}

/**
 *
 * @type {CouponFormContainer} container
 */
const container = ContainerFactory.get(CouponFormContainer);
export default container.withRouter(withStyles(CouponCodeFormStyle)(component));



