import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        paymentWrapper: {
            marginTop: theme.spacing(15)
        },
        paymentIcon: {
            fontSize: theme.spacing(8),
            align:"center",
            color: theme.palette.primary.main
        },
        selectPayment: {
            color: 'red'
        },
        totalAmount: {
            marginTop: theme.spacing(7),
            wordWrap: 'break-word'
        },
        paymentTitle: {
            fontSize: 16,
        }
    };
    fire('material_styles_payment_payment_listing', {theme, style});
    return style;
};

export default styles;


