import React from 'react';
import PropTypes from 'prop-types';
import {CoreComponent} from '../../../../framework/component/index'
import moment from "moment";
import ComponentFactory from "../../../../framework/factory/ComponentFactory";
import {TextField} from "@material-ui/core";

export class CustomerDateComponent extends CoreComponent {
    static className = 'CustomerDateComponent';
    select;

    /**
     * constructor
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {
            requiredInValid: false,
            date_value: props.DefaultValue
        }
    }

    /**
     * validate
     */
    validate() {
        let { Required } = this.props;
        let validate = Required &&  !this.state.date_value;
        this.setState({
            requiredInValid:  validate,
        });

        return validate;
    }

    /**
     * onchange date
     * @param event
     */
    onChangeDate(event) {
        let d = event.target.value ? moment(event.target.value).format('YYYY-MM-DD') : '';
        this.setState({date_value: d}, () => this.validate());
        if (this.props.onSelect) {
            this.props.onSelect(this.props.Code, d);
        }
    };

    /**
     * Is error
     *
     * @returns {*}
     */
    isError() {
        return this.state.requiredInValid;
    }

    /**
     * Get helper text
     *
     * @returns {string}
     */
    getHelperText() {
        let {requiredInValid} = this.state;
        let helperText = "";
        if (requiredInValid) {
            helperText = "This is a required field";
        }
        return helperText;
    }

    /**
     * Get input props
     *
     * @returns {{}}
     */
    getInputProps() {
        return {
            min: "1900-01-01"
        };
    }

    template() {
        let {Code, Label, DefaultValue, Required} = this.props;
        return (
            <TextField
                id={Code}
                required={Required}
                label={Label}
                type="date"
                defaultValue={DefaultValue}
                onChange={(event) => this.onChangeDate(event)}
                onKeyDown={(e) => e.preventDefault()}
                onFocus={(e) => e.target.blur()}
                error={this.isError()}
                helperText={this.getHelperText()}
                InputLabelProps={{
                    shrink: true,
                }}
                inputProps={this.getInputProps()}
            />
        );
    }
}

CustomerDateComponent.propTypes = {
    Label: PropTypes.string,
    Required: PropTypes.bool,
    OneRow: PropTypes.bool,
    Code: PropTypes.string,
    onSelect: PropTypes.func
};

/**
 * CustomerDateComponent
 */
export default ComponentFactory.get(CustomerDateComponent);



