import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        backdrop: {
            zIndex: theme.zIndex.drawer + 1,
        },
    };
    fire('material_styles_logout_logout', {theme, style});
    return style;
};

export default styles;


