import React, {Fragment} from 'react';
import CoreComponent from '../../../framework/component/CoreComponent';
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import AppBar from "@material-ui/core/AppBar";
import Toolbar from "@material-ui/core/Toolbar";
import Typography from "@material-ui/core/Typography";
import ArrowBack from '@material-ui/icons/ArrowBack';
import {IconButton} from "@material-ui/core";
import CartHeaderStyle from "../../style/material-styles/cart/CartHeaderStyle";
import {withStyles} from "@material-ui/core";
import QuoteAction from "../../action/checkout/QuoteAction";

export class CouponHeaderComponent extends CoreComponent {
    static className = 'CouponHeaderComponent';

    /**
     * Back to checkout cart
     */
    backToCheckoutCart() {
        let quote = this.props.quote;
        if (quote && quote.coupon_code) {
            this.props.actions.removeCouponCode(quote);
        }
        this.props.history.replace('/checkout/cart');
    }

    /**
     * Render template
     *
     * @returns {*}
     */
    template() {
        const {classes} = this.props;
        return (
            <Fragment>
                <AppBar>
                    <Toolbar>
                        <IconButton edge="start"
                                    onClick={() => this.backToCheckoutCart()}
                                    className={classes.backButton} color="inherit" aria-label="menu">
                            <ArrowBack />
                        </IconButton>
                        <Typography variant="h6" component="div">
                            {this.props.t('COUPON')}
                        </Typography>
                    </Toolbar>
                </AppBar>
                <Toolbar />
            </Fragment>
        );
    }
}

/**
 *  @type {CouponHeaderComponent}
 */
const component = ComponentFactory.get(CouponHeaderComponent);

class CouponHeaderContainer extends CoreContainer {
    static className = 'CouponHeaderContainer';

    /**
     *
     * @param state
     * @return {{quote: *}}
     */
    static mapState(state) {
        const {quote} = state.core.checkout;
        return {
            quote
        }
    }

    /**
     *
     * @param dispatch
     * @return {{actions: {placeOrder, placeOrderResult, placeOrderError, checkoutToSelectPayments}|ActionCreator<any>|ActionCreatorsMapObject}}
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                removeCouponCode: (quote) => dispatch(QuoteAction.removeCouponCode(quote))
            }
        }
    }
}

/**
 *
 * @type {CouponHeaderContainer}
 */
const container = ContainerFactory.get(CouponHeaderContainer);
export default container.withRouter(withStyles(CartHeaderStyle)(component));



