import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        addNewCustomerButton: {
            position: 'fixed',
            right: theme.spacing(1),
        },
    };
    fire('material_styles_customer_add_new_customer_button_style', {theme, style});
    return style;
};

export default styles;



