import RestAbstract from "./RestAbstract";
import DataResourceFactory from "../../../framework/factory/DataResourceFactory";

export class RestLocation extends RestAbstract {
    static className = 'RestLocation';

    get_list_api = "/V1/webpos/availableLocation";
    assign_pos_api = "/V1/webpos/posassign";

    /**
     * assign pos
     * @returns {promise}
     */
    assignPos(posId, locationId, currentStaffId) {
        let params = {
            pos: {
                pos_id: posId,
                location_id: locationId
            }
        };
        let url = this.getBaseUrl() + this.assign_pos_api;
        return this.post(url, params);
    }
}

/**
 * @type {RestLocation}
 */
export default DataResourceFactory.get(RestLocation);




