import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestLocation from "./rest/RestLocation";
import GraphqlLocation from "./graphql/GraphqlLocation";

export default class OmcLocation extends OmcAbstract {
    static className = 'OmcLocation';

    apiResources = {
        [ApiResourceConstant.REST]: RestLocation,
        [ApiResourceConstant.GRAPHQL]: GraphqlLocation,
    };

    /**
     * assign pos
     * @returns {promise}
     */
    assignPos(posId, locationId, currentStaffId) {
        return this.getRestResource().assignPos(posId, locationId, currentStaffId);
    }
}




