import React, {Fragment} from 'react';
import CoreComponent from '../../../framework/component/CoreComponent';
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import AppBar from "@material-ui/core/AppBar";
import Toolbar from "@material-ui/core/Toolbar";
import Typography from "@material-ui/core/Typography";
import ArrowBack from '@material-ui/icons/ArrowBack';
import {IconButton} from "@material-ui/core";
import CartHeaderStyle from "../../style/material-styles/cart/CartHeaderStyle";
import {withStyles} from "@material-ui/core";
import CustomerButton from "../customer/CustomerButton";

export class CartHeaderComponent extends CoreComponent {
    static className = 'CartHeaderComponent';

    /**
     * Render template
     *
     * @returns {*}
     */
    template() {
        const {classes} = this.props;
        return (
            <Fragment>
                <AppBar>
                    <Toolbar>
                        <IconButton edge="start"
                                    onClick={() => this.props.history.replace('/checkout')}
                                    className={classes.backButton} color="inherit" aria-label="menu">
                            <ArrowBack />
                        </IconButton>
                        <Typography variant="h6" component="div">
                            {this.props.t('CART')}
                        </Typography>
                        <CustomerButton />
                    </Toolbar>
                </AppBar>
                <Toolbar />
            </Fragment>
        );
    }
}

/**
 *  @type {CartHeaderComponent}
 */
const component = ComponentFactory.get(CartHeaderComponent);

class CartHeaderContainer extends CoreContainer {
    static className = 'CartHeaderContainer';
}

/**
 *
 * @type {CartHeaderContainer}
 */
const container = ContainerFactory.get(CartHeaderContainer);
export default container.withRouter(withStyles(CartHeaderStyle)(component));



