/* eslint-disable react/prop-types */
import React from 'react';
import ReactDOM from 'react-dom';
import {Provider} from 'react-redux';
import {HashRouter as Router, Route, Switch, Redirect} from 'react-router-dom';
import AppStore from './view/store/store';
import Login from './view/component/user/Login';
import Index from './view/Index';
import Loading from './view/component/loading/Loading';
import registerServiceWorker from './registerServiceWorker';
import SelectLocationPos from "./view/component/user/SelectLocationPos";
import App from "./App";
import i18n from './config/i18n';
import { I18nextProvider } from 'react-i18next';
import UserService from "./service/user/UserService";
import Events from './view/component/events'
import {createTheme, MuiThemeProvider} from "@material-ui/core/styles";
import MaterialThemeService from "./service/material-ui/MaterialThemeService";
import CartComponent from "./view/component/checkout/Cart";
import CouponComponent from "./view/component/checkout/Coupon";
import PaymentComponent from "./view/component/checkout/Payment";
import CheckoutSuccessComponent from "./view/component/checkout/Success";

let isLogin = (pathname) => {
    let session = UserService.getSession();
    if (pathname !== '/login' && !session) {
        return false;
    } else if (pathname !== '/login' && session) {
        return true;
    }
    return true;
}

const PrivateRoute = ({ component: Component, ...rest }) => (
    <Route
        {...rest}
        render={props =>
            isLogin(props.location.pathname) ? (
                <Component {...props} />
            ) : (
                <Redirect
                    to={{
                        pathname: "/login"
                    }}
                />
            )
        }
    />
);

const theme = createTheme(MaterialThemeService.getThemeOptions());

ReactDOM.render(
    <I18nextProvider i18n={ i18n }>
    <Provider store={AppStore}>
        <Router>
            <div>
                <MuiThemeProvider theme={theme}>
                    <PrivateRoute component={App}/>
                    <Switch>
                        <PrivateRoute path="/login" exact component={Login}/>
                        <PrivateRoute path="/loading" exact component={Loading}/>
                        <PrivateRoute path="/locations" exact component={SelectLocationPos}/>
                        <PrivateRoute path="/checkout/cart" exact component={CartComponent}/>
                        <PrivateRoute path="/checkout/coupon" exact component={CouponComponent}/>
                        <PrivateRoute path="/checkout/payment" exact component={PaymentComponent}/>
                        <PrivateRoute path="/checkout/success" exact component={CheckoutSuccessComponent}/>
                        <PrivateRoute path="/" component={Index}/>
                    </Switch>
                    <Events/>
                </MuiThemeProvider>
            </div>
        </Router>
    </Provider>
    </I18nextProvider>,
    document.getElementById('root'));
registerServiceWorker();



