import React from 'react';
import PropTypes from 'prop-types';
import {CoreComponent} from '../../../../framework/component/index';
import ComponentFactory from "../../../../framework/factory/ComponentFactory";
import {MenuItem, TextField, withStyles} from "@material-ui/core";
import CustomerGroupStyle from "../../../style/material-styles/customer/fields/CustomerGroupStyle";

export class CustomerGroupComponent extends CoreComponent {
    static className = 'CustomerGroupComponent';
    select;

    /**
     * constructor
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {
            options: props.Options,
            requiredInValid: false,
            defaultValue: props.DefaultValue
        }
    }

    /**
     * componentWillReceiveProps
     * @param nextProps
     */
    componentWillReceiveProps(nextProps) {
        this.setState({options: nextProps.Options});
    }

    /**
     * set select
     * @param select
     */
    setSelect(select) {
        this.select = select;
    }

    /**
     * Set value
     * @param value
     */
    setValue(value) {
        if (value) {
            this.select.value = value;
            this.setState({defaultValue: this.select.value});
        } else {
            this.select.value = '';
        }
    }

    /**
     * onchange
     * @param event
     */
    onChange(event) {
        this.setState({defaultValue: event.target.value}, () => this.validate());
        if (this.props.onSelect) {
            this.props.onSelect(this.props.Code, event.target.value);
        }
    }

    /**
     * set options
     * @param options
     */
    setOptions(options) {
        this.setState({options: options});
    }

    /**
     * validate
     * @return {CustomerGroupComponent.props.Required|boolean}
     */
    validate() {
        let { Required } = this.props;
        let validate = Required && !this.select.value;
        this.setState({
            requiredInValid:  validate,
        });
        return validate;
    }

    /**
     * clear
     */
    clear() {
        if (this.select) {
            this.select.value = "";
        }

        this.validate();
    }

    /**
     * onclick show message error
     */
    onClickShowMessageError() {
        this.setState({showMessageInValid: true});
    }

    /**
     * Get default value for select
     *
     * @returns {number|*}
     */
    getDefaultValueSelect() {
        let hasNullOption = false;
        this.state.options.map(option => {
            if (option.value === '') {
                hasNullOption = true;
            }
            return option;
        });

        if (this.state.defaultValue === '' && !hasNullOption) {
            return 0;
        } else {
            return this.state.defaultValue;
        }
    }

    /**
     * Is error
     *
     * @returns {*}
     */
    isError() {
        return this.state.requiredInValid;
    }

    /**
     * Get helper text
     *
     * @returns {string}
     */
    getHelperText() {
        let {requiredInValid} = this.state;
        let helperText = "";
        if (requiredInValid) {
            helperText = "This is a required field";
        }
        return helperText;
    }

    /**
     * Get select props
     *
     * @returns {{}}
     */
    getSelectProps() {
        let {classes} = this.props;
        return {
            MenuProps: {
                className: classes.menu
            },
        };
    }

    template() {
        let { Code, Label, KeyValue, KeyTitle, Required, isDisabled, t} = this.props;
        return (
            <TextField
                required={Required}
                disabled={isDisabled}
                fullWidth
                id={Code}
                label={t(Label)}
                select
                value={this.getDefaultValueSelect()}
                InputLabelProps={{
                    shrink: true,
                }}
                SelectProps={this.getSelectProps()}
                error={this.isError()}
                helperText={t(this.getHelperText())}
                inputRef={this.setSelect.bind(this)}
                onChange={this.onChange.bind(this)}
            >
                {
                    this.state.options ? this.state.options.map(option => {
                        return (<MenuItem key={Math.random()} value={option[KeyValue]}> {option[KeyTitle]} </MenuItem>)
                    }) : null
                }
            </TextField>
        );
    }
}

CustomerGroupComponent.propTypes = {
    Label: PropTypes.string,
    Options: PropTypes.array,
    KeyValue: PropTypes.string,
    KeyTitle: PropTypes.string,
    Required: PropTypes.bool,
    OneRow: PropTypes.bool,
    Code: PropTypes.string,
    onSelect: PropTypes.func
};

/**
 * CustomerGroupComponent
 */
export default withStyles(CustomerGroupStyle)(ComponentFactory.get(CustomerGroupComponent));



