import React from 'react';
import CoreComponent from "../../../../framework/component/CoreComponent";
import ComponentFactory from "../../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../../framework/container/CoreContainer";
import ContainerFactory from "../../../../framework/factory/ContainerFactory";
import {Button, Container, Dialog, IconButton, TextField, withStyles} from "@material-ui/core";
import Toolbar from "@material-ui/core/Toolbar";
import ArrowBack from "@material-ui/icons/ArrowBack";
import Typography from "@material-ui/core/Typography";
import AppBar from "@material-ui/core/AppBar";
import EditCartItemStyle from "../../../style/material-styles/cart/item/EditCartItemStyle";
import StockService from "../../../../service/catalog/StockService";
import QuoteItemService from "../../../../service/checkout/quote/ItemService";
import ProductTypeConstant from "../../../constant/ProductTypeConstant";
import QuoteAction from "../../../action/checkout/QuoteAction";
import CheckoutAction from "../../../action/CheckoutAction";

export class EditCartItemComponent extends CoreComponent {
    static className = 'EditCartItemComponent';

    qtyInputRef;

    constructor(props) {
        super(props);
        this.state = {
            error: false,
            helperText: ''
        }
    }

    /**
     * Reset State
     */
    resetState() {
        this.setState({
            error: false,
            helperText: ''
        });
    }

    /**
     * Back to cart
     */
    backToCart() {
        this.resetState();
        this.props.actions.closeEditCartItemPage();
        if (!(this.props.quote.applied_rule_ids && this.props.quote.applied_rule_ids.includes('POS_CUSTOM_DISCOUNT'))) {
            this.props.actions.validateQuoteSalesRule(this.props.quote);
        }
    }

    /**
     * Get Qty Input Props
     *
     * @returns {{}}
     */
    getQtyInputProps() {
        let {currentItem, quote} = this.props;
        let childItem = false;

        if (currentItem.product_type === ProductTypeConstant.CONFIGURABLE) {
            childItem = QuoteItemService.getChildrenItems(quote, currentItem)[0];
        }

        const realProduct = childItem ? childItem.product : currentItem.product;
        let {qtyIncrement} = StockService.getStockInfo(realProduct);
        return {
            min: 0,
            step: Number(qtyIncrement)
        };
    }

    /**
     * Handle change qty
     *
     * @param event
     */
    handleChangeQty(event) {
        if (event.target.value) {
            let newQty = Number(event.target.value);
            this.setState({
                error: false,
                helperText: ''
            });
            if (newQty !== this.props.currentItem.qty) {
                this.props.actions.updateQtyCartItem(this.props.currentItem, newQty);
            }
        } else {
            this.setState({
                helperText: this.props.t('Quantity is required!'),
                error: true
            })
        }
    }

    /**
     * Remove Product
     */
    removeProduct() {
        this.props.actions.removeCartItem(this.props.currentItem);
        this.backToCart();
    }

    /**
     *  render template
     * @return {*}
     */
    template() {
        let {currentItem, showEditCartItemPage, classes} = this.props;
        if (!currentItem) {
            return null;
        }
        return (
            <Dialog fullScreen open={showEditCartItemPage} onClose={() => this.backToCart()}>
                <AppBar>
                    <Toolbar>
                        <IconButton edge="start"
                                    onClick={() => this.backToCart()}
                                    color="inherit" aria-label="menu">
                            <ArrowBack />
                        </IconButton>
                        <Typography variant="h6" component="div" noWrap>
                            {currentItem.name}
                        </Typography>
                    </Toolbar>
                </AppBar>
                <Container maxWidth={'sm'} className={classes.contentWrapper}>
                    <TextField
                        id="qty-input"
                        margin="normal"
                        className={classes.qtyInput}
                        fullWidth
                        autoFocus
                        required
                        inputRef={(c) => {this.qtyInputRef = c;}}
                        label={this.props.t('Quantity')}
                        type="number"
                        defaultValue={currentItem.qty}
                        inputProps={this.getQtyInputProps()}
                        onChange={(event) => this.handleChangeQty(event)}
                        helperText={this.state.helperText}
                        error={this.state.error}
                    />
                    <Button color="secondary"
                            onClick={() => this.removeProduct()}
                    >
                        {this.props.t('Remove product')}
                    </Button>
                </Container>
            </Dialog>
        );
    }
}

/**
 *
 * @type {EditCartItemComponent}
 */
const component = withStyles(EditCartItemStyle)(ComponentFactory.get(EditCartItemComponent));

class EditCartItemContainer extends CoreContainer {
    static className = 'EditCartItemContainer';

    /**
     *
     * @inheritDoc
     */
    static mapState(state) {
        const {index, quote} = state.core.checkout;
        const {showEditCartItemPage, currentItem} = index;
        return {
            quote,
            showEditCartItemPage,
            currentItem
        };
    }

    /**
     *
     * @param dispatch
     * @return {{actions: {setQuote, addProduct, addProductSuccess, addProductFail, removeCartItem, removeCartItemSuccess, removeCartItemFail, updateQtyCartItem, updateQtyCartItemSuccess, updateQtyCartItemFail, setPayments}|ActionCreator<any>|ActionCreatorsMapObject}}
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                updateQtyCartItem: (item, qty) => dispatch(QuoteAction.updateQtyCartItem(item, qty)),
                removeCartItem: (item) => dispatch(QuoteAction.removeCartItem(item)),
                closeEditCartItemPage: () => dispatch(CheckoutAction.closeEditCartItemPage()),
                validateQuoteSalesRule: (quote) => dispatch(QuoteAction.validateQuoteSalesRule(quote))
            }
        }
    }
}

/**
 *
 * @type {EditCartItemContainer}
 */
const container = ContainerFactory.get(EditCartItemContainer);

export default container.getConnect(component);



