import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        customerButton: {
            position: 'fixed',
            right: theme.spacing(1),
            maxWidth: '50%',
            textTransform: 'none'
        },
    };
    fire('material_styles_customer_customer_button_style', {theme, style});
    return style;
};

export default styles;



