import {fire} from "../../../../../event-bus";

const styles = theme => {
    let style = {
        backButton: {
            marginRight: theme.spacing(0),
        },
        formGroup: {
            marginTop: theme.spacing(1),
        },
    };
    fire('material_styles_customer_address_address_customer_popup_style', {theme, style});
    return style;
};

export default styles;



