import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestPerformance from "./rest/RestPerformance";
import GraphqlPerformance from "./graphql/GraphqlPerformance";

export default class OmcPerformance extends OmcAbstract {
    static className = 'OmcPerformance';

    apiResources = {
        [ApiResourceConstant.REST]: RestPerformance,
        [ApiResourceConstant.GRAPHQL]: GraphqlPerformance,
    };

    /**
     * Sync saved data to server
     *
     * @param params
     *
     * @return promise
     */
    saveLog(params) {
        return this.getRestResource().saveLog(params);
    }
}




