import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestCategory from "./rest/RestCategory";
import GraphqlCategory from "./graphql/GraphqlCategory";

export default class OmcCategory extends OmcAbstract {
    static className = 'OmcCategory';

    apiResources = {
        [ApiResourceConstant.REST]: RestCategory,
        [ApiResourceConstant.GRAPHQL]: GraphqlCategory
    };
}



