import Abstract from './IndexedDbAbstract';

export default class IndexedDbPerformance extends Abstract {
    static className = 'IndexedDbPerformance';

    main_table = 'performance_track';
    primary_key = 'id';
    offline_id_prefix = '';

    /**
     * Get all data of table
     * @returns {Promise<any>}
     */
    getAll() {
        return this.db[this.main_table].toCollection().sortBy('sort_order');
    }


    /**
     * Delete all data of table
     * @returns {Promise<any>}
     */
    deleteAll() {
        return this.db[this.main_table].clear();
    }
}



