import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestStock from "./rest/RestStock";
import GraphqlStock from "./graphql/GraphqlStock";

export default class OmcStock extends OmcAbstract {
    static className = 'OmcStock';

    apiResources = {
        [ApiResourceConstant.REST]: RestStock,
        [ApiResourceConstant.GRAPHQL]: GraphqlStock,
    };

    /**
     * get available qty from server
     * @param productId
     * @returns {Promise<any>}
     */
    getQty(productId) {
        return this.getRestResource().getQty(productId);
    }

    /**
     * get external stock from server
     * @param product_id
     * @returns {Promise.<any>}
     */
    getExternalStock(product_id) {
        return this.getRestResource().getExternalStock(product_id);
    }

    /**
     * Get list via api
     *
     * @param {object} queryService
     * @return {Promise<any>}
     */
    getStockItemsToRefund(queryService = {}) {
        return this.getRestResource().getStockItemsToRefund(queryService);
    }

    /**
     * Get stock products from product ids
     *
     * @param productIds
     */
    getStockProducts(productIds) {
        return this.getRestResource().getStockProducts(productIds);
    }
}




