import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        cartTotalsWrapper: {
            backgroundColor: '#f5f5f5',
        },
        cartTotalsItem: {
            textAlign: 'right',
            paddingTop: 0,
            paddingBottom: 0
        },
        totalText: {
            fontWeight: 'bold'
        }
    };
    fire('material_styles_cart_cart_totals_style', {theme, style});
    return style;
};

export default styles;



