import React, {Fragment} from 'react';
import CoreComponent from "../../../framework/component/CoreComponent";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import Container from "@material-ui/core/Container";
import AppBar from "@material-ui/core/AppBar";
import Button from "@material-ui/core/Button";
import Toolbar from "@material-ui/core/Toolbar";
import Typography from "@material-ui/core/Typography";
import Check from '@material-ui/icons/Check';
import SuccessStyle from "../../style/material-styles/payment/Success";
import {withStyles} from "@material-ui/core";
import i18n from "../../../config/i18n";
import layout from "../../../framework/Layout";

export class SuccessComponent extends CoreComponent {
    static className = 'SuccessComponent';

    /**
     * Component will mount
     */
    componentWillMount() {
        if (!(this.props.lastOrder && this.props.lastOrder.increment_id)) {
            // No item redirect to product list
            this.props.history.replace('/checkout');
        }
    }

    /**
     * Start new sale
     */
    startNewSale() {
        this.props.history.replace('/checkout');
    }

    /**
     * render template
     *
     * @returns {*}
     */
    template() {
        const { t, classes, lastOrder } = this.props;
        return (
            lastOrder ?
            <Fragment>
                <Toolbar />
                <Container align="center">
                    <Check className={classes.check} />
                </Container>

                <Container  className={classes.doneContainer}>
                    <Typography variant="h5" component="div" align="center">
                        {
                            i18n.translator.translate(
                                'Order #{{id}} has been created successfully!',
                                {id: lastOrder.increment_id}
                            )
                        }
                    </Typography>
                    {layout('checkout')('success')('success_text_after')()(this)}
                </Container>


                <Toolbar />
                <AppBar position="fixed" color="primary"
                        className={classes.newSaleWrapper} >
                    <Button variant="contained" color="primary"
                            className={classes.newSaleButton} onClick={() => this.startNewSale()}>
                        {t('Start A New Sale')}
                    </Button>
                </AppBar>
            </Fragment> : ''
        );
    }
}

/**
 *
 * @type {SuccessComponent}
 */
const component = ComponentFactory.get(SuccessComponent);

export class SuccessContainer extends CoreContainer{
    static className = 'SuccessContainer';

    /**
     * map state to props
     * @param state
     * @returns {{payments: (Payment.state.payment.payments|String.payments|*),
     * payments_selected: (Payment.state.payment.payments|String.payments|*|Array)}}
     */
    static mapState(state) {
        let {lastOrder} = state.core.checkout.index;
        return {
            lastOrder: lastOrder
        };
    }
}

/**
 *
 * @type {SuccessContainer}
 */
const container = ContainerFactory.get(SuccessContainer);
export default container.getConnect(withStyles(SuccessStyle)(component));



