import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        wrapperSharingAccount: {
            marginTop: '40%',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
        },
        switchDeviceImage: {
            marginBottom: theme.spacing(4),
            height: '100%',
            width: theme.spacing(30),
            maxWidth: '80%',
        },
        content: {
            color: '#3f4245',
            marginTop: theme.spacing(1),
        },
        wrapperButton: {
            marginTop: theme.spacing(4)
        },
        continueButton: {
            marginLeft: theme.spacing(1)
        }
    };
    fire('material_styles_user_sharing_account_popup', {theme, style});
    return style;
};

export default styles;


