import React, {Fragment} from 'react';
import CoreComponent from "../../../framework/component/CoreComponent";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import CartHeaderComponent from "../cart/CartHeaderComponent";
import CartFooterComponent from "../cart/CartFooterComponent";
import CartItems from "../cart/CartItems";
import CartTotals from "../cart/CartTotals";
import EditCartItem from "../cart/item/EditCartItem";
import layout from "../../../../src/framework/Layout";

export class CartComponent extends CoreComponent {
    static className = 'CartComponent';



    /**
     * render template
     *
     * @returns {*}
     */
    template() {
        return (
            <Fragment>
                <CartHeaderComponent />
                <CartItems history={this.props.history} />
                <CartTotals />
                <CartFooterComponent />
                <EditCartItem />
                {layout('checkout')('cart')('edit_cart_item_after')()(this)}
            </Fragment>
        );
    }
}

/**
 *
 * @type {CartComponent}
 */
const component = ComponentFactory.get(CartComponent);

export class CartContainer extends CoreContainer{
    static className = 'CartContainer';
}

/**
 *
 * @type {CartContainer}
 */
const container = ContainerFactory.get(CartContainer);
export default container.getConnect(component);



