import {fire} from "../../../../../event-bus";

const styles = theme => {
    let style = {
        backdrop: {
            zIndex: theme.zIndex.drawer + 1,
        }
    };
    fire('material_styles_cart_totals_cart_totals_discount_style', {theme, style});
    return style;
};

export default styles;



