import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        productSku: {
            display: 'block',
            width: '100%'
        },
        productPrice: {
            display: 'block',
            width: '100%',
            fontWeight: 'bold'
        },
        productName: {
            wordWrap: 'break-word'
        },
        wrapperAvatar: {
            marginRight: theme.spacing(3),
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center'
        }
    };
    fire('material_styles_catalog_product_style', {theme, style});
    return style;
};

export default styles;



