import React, {Fragment} from 'react';
import CoreComponent from "../../../framework/component/CoreComponent";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import CouponHeaderComponent from "../coupon/CouponHeaderComponent";
import CouponFormComponent from "../coupon/CouponFormComponent";
import CartFooterComponent from "../cart/CartFooterComponent";
import CartTotals from "../cart/CartTotals";
import layout from "../../../../src/framework/Layout";

export class CouponComponent extends CoreComponent {
    static className = 'CouponComponent';

    /**
     * render template
     *
     * @returns {*}
     */
    template() {
        return (
            <Fragment>
                <CouponHeaderComponent />
                <CouponFormComponent />
                <CartTotals />
                <CartFooterComponent />
                {layout('checkout')('cart')('edit_cart_item_after')()(this)}
            </Fragment>
        );
    }
}

/**
 *
 * @type {CouponComponent}
 */
const component = ComponentFactory.get(CouponComponent);

export class CouponContainer extends CoreContainer{
    static className = 'CouponContainer';
}

/**
 *
 * @type {CouponContainer}
 */
const container = ContainerFactory.get(CouponContainer);
export default container.getConnect(component);



