import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        check: {
            fontSize: theme.spacing(25),
            align: "center",
            color: "green"
        },
        newSaleButton: {
            height: '100%',
            fontSize: 20,
            fontWeight: 'bold'
        },
        newSaleWrapper: {
            top: 'auto',
            height: theme.spacing(7),
            bottom: 0
        },
        doneContainer: {
            marginTop: theme.spacing(7)
        }
    };
    fire('material_styles_payment_success', {theme, style});
    return style;
};

export default styles;


