import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        complete: {
            backgroundColor: '#c2dcf2'
        },
        processing: {
            backgroundColor: 'pink'
        },
        paid: {
            color: '#1e88e5'
        },
        void: {
            color: '#7b7b7b'
        },
        due: {
            color: '#d23734'
        },
        orderAmountDetail: {
            textAlign: 'right'
        },
        dividerItem: {
            marginLeft: theme.spacing(2)
        }
    };
    fire('material_styles_order_order_style', {theme, style});
    return style;
};

export default styles;



