import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        root: {
            flexGrow: 1,
        },
        left: {
            textAlign: 'left'
        },
        right: {
            textAlign: 'right'
        },
        itemDetailQty: {
            marginRight: theme.spacing(2)
        },
        dividerItem: {
            marginLeft: theme.spacing(2)
        }
    };
    fire('material_styles_order_order_item_style', {theme, style});
    return style;
};

export default styles;



