import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestSession from "./rest/RestSession";
import GraphqlSession from "./graphql/GraphqlSession";

export default class OmcSession extends OmcAbstract {
    static className = 'OmcSession';

    apiResources = {
        [ApiResourceConstant.REST]: RestSession,
        [ApiResourceConstant.GRAPHQL]: GraphqlSession,
    };

    /**
     * get path shift save
     * @returns string
     */
    getPathShiftSave() {
        return this.getRestResource().getPathShiftSave();
    }

    /**
     * get path cash transaction save
     * @returns string
     */
    getPathCashTransactionSave() {
        return this.getRestResource().getPathCashTransactionSave();
    }

    /**
     * Get list via api
     * @param queryService
     * @param isSync
     * @returns {Promise<any>}
     */
    getList(queryService, isSync = false) {
        return this.getRestResource().getList(queryService, isSync);
    }
}



