import {fire} from "../../../../../event-bus";

const styles = theme => {
    let style = {
        menu: {
            maxHeight: theme.spacing(40),
        },
    };
    fire('material_styles_customer_fields_customer_group_style', {theme, style});
    return style;
};

export default styles;



