import RestAbstract from "./RestAbstract";
import PosService from "../../../service/PosService";
import DataResourceFactory from "../../../framework/factory/DataResourceFactory";

export class RestSession extends RestAbstract {
    static className = 'RestSession';

    get_list_api = "/V1/webpos/shifts/getlist";
    shift_save_api = "/V1/webpos/shifts/save";
    cash_transaction_save_api = "/V1/webpos/cash_transaction/save";

    /**
     * get path shift save
     * @returns string
     */
    getPathShiftSave() {
        return this.shift_save_api;
    }

    /**
     * get path cash transaction save
     * @returns string
     */
    getPathCashTransactionSave() {
        return this.cash_transaction_save_api;
    }

    /**
     * Get list via api
     * @param queryService
     * @param isSync
     * @returns {Promise<any>}
     */
    getList(queryService, isSync = false) {
        queryService.addFieldToFilter('pos_id', PosService.getCurrentPosId(), 'eq');
        return super.getList(queryService, isSync);
    }
}

/**
 * @type {RestSession}
 */
export default DataResourceFactory.get(RestSession);



