import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        wrapperLoading: {
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)'
        },
        percentText: {
            fontSize: theme.spacing(10)
        },
        circle: {
            strokeLinecap: 'round',
        }
    };
    fire('material_styles_loading_loading', {theme, style});
    return style;
};

export default styles;


