import React, { Fragment } from 'react';
import CoreComponent from "../../../framework/component/CoreComponent";
import CoreContainer from "../../../framework/container/CoreContainer";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import ReceiptService from "../../../service/receipt/ReceiptService";
import LocationService from "../../../service/LocationService";
import DateTimeHelper from "../../../helper/DateTimeHelper";
import AddressConstant from "../../constant/checkout/quote/AddressConstant";
import layout from "../../../framework/Layout";
import PropTypes from "prop-types";
import UserService from "../../../service/user/UserService";

export class HeaderReceiptComponent extends CoreComponent {
    static className = 'HeaderReceiptComponent';

    templateLogo() {
        const receiptLogo = ReceiptService.getReceiptLogo();
        const receiptLogoWidth = ReceiptService.getReceiptLogoWidth();
        const receiptLogoHeight = ReceiptService.getReceiptLogoHeight();

        return (
            <img id={"receipt-logo"}
                 className={(receiptLogo) ? "" : "hidden"}
                 src={receiptLogo}
                 alt={"logo"}
                 width={receiptLogoWidth}
                 height={receiptLogoHeight}/>
        );
    }

    templateHeader() {
        const receiptHeader = LocationService.getCurrentLocationHeader();

        return (
            <div id={"receipt-header"}
                 className={(receiptHeader) ? "" : "hidden"}
                 dangerouslySetInnerHTML={{__html: receiptHeader}} />
        );
    }

    templateCompanyName() {
        const companyName = LocationService.getCurrentStoreName();

        return (
            <div id={"receipt-company-name"} className={(companyName) ? "title" : "hidden"}>{companyName}</div>
        );
    }

    templateLocationName() {
        const locationName = LocationService.getCurrentLocationName();

        return (
            <Fragment>
                <p id={"receipt-location-name"} className={(locationName) ? "" : "hidden"}>{locationName}</p>
                <br/>
            </Fragment>
        );
    }

    templateLocationAddress() {
        const locationAddress = ReceiptService.getDisplayLocationAddress();

        return (
            <p id={"receipt-location-address"} className={(locationAddress) ? "" : "hidden"}>{locationAddress}</p>
        );
    }

    templateLocationTelephone() {
        const locationTelephone = LocationService.getCurrentLocationTelephone();

        return (
            <p id={"receipt-location-telephone"} className={(locationTelephone) ? "" : "hidden"}>{locationTelephone}</p>
        );
    }

    templateIncrementId() {
        const { orderData, creditmemoIncrementId } = this.props;
        let incrementId = (orderData.increment_id) ? ("" + orderData.increment_id) : "";

        if (creditmemoIncrementId) {
            incrementId = creditmemoIncrementId;
        }

        const createAt = DateTimeHelper.getReceiptDateTime(orderData.created_at);

        return (
            <tr id={"receipt-increment-id"}>
                <td>#{incrementId}</td>
                <td className="text-right">{createAt}</td>
            </tr>
        );
    }

    templateLocationPlacedOrder() {
        const { orderData, t } = this.props;
        const locationPlacedOrder = LocationService.getDisplayLocation(orderData);

        return (
            <tr id={"receipt-location-placed-order"} className={"created-at-location-field"}>
                <td>{t('Created At Location')}</td>
                <td className="text-right">{locationPlacedOrder}</td>
            </tr>
        );
    }

    templateOriginOrderId() {
        const { orderData, t } = this.props;
        const originOrderId = (orderData.increment_id) ? ("" + orderData.increment_id) : "";

        return (
            <tr id={"receipt-origin-order-id"}>
                <td>{t('Original Order')}</td>
                <td className="text-right">#{originOrderId}</td>
            </tr>
        )
    }

    templateCashier() {
        const { orderData, t, creditmemoIncrementId } = this.props;
        const staffName = creditmemoIncrementId ? UserService.getStaffName() : orderData.pos_staff_name;

        return (
            <tr id={"receipt-cashier"}>
                <td>{t('Cashier')}</td>
                <td className="text-right">{staffName}</td>
            </tr>
        );
    }

    templateCustomerName() {
        const { orderData, t } = this.props;
        const customerName = ReceiptService.getFullName(orderData);

        return (
            <tr id={"receipt-customer-name"} className={!orderData.customer_is_guest ? "" : "hidden"}>
                <td>{t('Customer')}</td>
                <td className="text-right">{customerName}</td>
            </tr>
        );
    }

    templatePhone() {
        const { orderData, t } = this.props;
        let phone = "";
        let addresses = orderData.addresses;
        addresses.map(addess => {
            if (addess.address_type === AddressConstant.SHIPPING_ADDRESS_TYPE) {
                phone = addess.telephone;
            }
            return addess
        });

        return (
            <tr id={"receipt-phone"} className={!orderData.customer_is_guest ? "" : "hidden"}>
                <td>{t('Phone')}</td>
                <td className="text-right">{phone}</td>
            </tr>
        );
    }

    templateRefundTitle(title) {
        return (
            <Fragment>
                <br/>
                <div id={"receipt-refund-title"} className="title">{title}</div>
                <br/>
            </Fragment>
        )
    }

    /**
     * Template
     *
     * @returns {JSX.Element}
     */
    template() {
        const { orderData, creditmemoIncrementId, t } = this.props;

        return (
            <Fragment>
                {this.templateLogo()}
                {this.templateHeader()}
                {this.templateCompanyName()}
                {this.templateLocationName()}
                {this.templateLocationAddress()}
                {this.templateLocationTelephone()}
                {creditmemoIncrementId ? this.templateRefundTitle(t('Refund Receipt')) : null}
                <table>
                    <tbody>
                    <tr>
                        <td colSpan="4">
                            <hr/>
                        </td>
                    </tr>
                    {this.templateIncrementId()}
                    {creditmemoIncrementId ? this.templateOriginOrderId() : this.templateLocationPlacedOrder()}
                    {this.templateCashier()}
                    {
                        creditmemoIncrementId ?
                            layout('print')('cashier_name_layout')('refund_cashier_name_after')()(this, orderData) :
                            layout('print')('cashier_name_layout')('receipt_cashier_name_after')()(this, orderData)
                    }
                    {this.templateCustomerName()}
                    {this.templatePhone()}
                    <tr>
                        <td colSpan="4">
                            <hr/>
                        </td>
                    </tr>
                    </tbody>
                </table>
            </Fragment>
        )
    }
}

HeaderReceiptComponent.propsTypes = {
    orderData: PropTypes.object,
    creditmemoIncrementId: PropTypes.string,
};

class HeaderReceiptContainer extends CoreContainer {
    static className = 'HeaderReceiptContainer';
}

/**
 * @type {HeaderReceiptComponent}
 */
export default ContainerFactory.get(HeaderReceiptContainer).withRouter(
    ComponentFactory.get(HeaderReceiptComponent)
);



