import React, {Fragment} from 'react';
import PropTypes from 'prop-types';
import {CoreComponent} from '../../../../framework/component/index';
import CustomerConstant from "../../../constant/CustomerConstant";
import Config from "../../../../config/Config";
import ConfigHelper from "../../../../helper/ConfigHelper";
import AddCustomerPopupConstant from "../../../constant/customer/AddCustomerPopupConstant";
import ComponentFactory from "../../../../framework/factory/ComponentFactory";
import DeviceHelper from "../../../../helper/DeviceHelper";
import CustomerService from '../../../../service/customer/CustomerService';
import {IconButton, InputAdornment, TextField} from "@material-ui/core";
import ClearIcon from '@material-ui/icons/Clear';
import GoogleSuggestComponent from "../address/GoogleSuggestComponent";

export class CustomerInputComponent extends CoreComponent {
    static className = 'CustomerInputComponent';
    regexEmail = ConfigHelper.regexEmail;
    input;

    /**
     * constructor
     * @param props
     */
    constructor(props) {
        super(props);
        let state = {
            canClear: false,
            requiredInValid: false,
            requiredBlankInValid: false,
            requiredEmailInValid: false,
            isEmailAvailable: true,
            showGoogleSuggest: false,
            defaultValue: props.DefaultValue,
            showWarningMessage: false,
            IsRequired: props.Required
        };
        if(props.Code === AddCustomerPopupConstant.ATTRIBUTE_CODE_POSTCODE) {
            state.IsRequired = !props.IsOptional;
        }
        this.state = state;
    }

    /**
     * @inheritDoc
     */
    componentWillUnmount() {
        if (this.timeOut) {
            clearTimeout(this.timeOut);
        }
    }

    /**
     * set input
     * @param input
     */
    setInput(input) {
        this.input = input;
    }

    /**
     * hidden google suggest
     */
    hiddenGoogleSuggest() {
        this.setState({showGoogleSuggest: false});
    }

    /**
     * hidden clear input
     */
    hiddenClearInput() {
        this.setState({canClear: false});
    }

    /**
     * set value
     * @param value
     */
    setValue(value) {
        if (value) {
            this.input.value = value;
        } else {
            this.input.value = '';
        }
        this.setState({
            canClear: this.input.value.length,
            requiredInValid: false,
            requiredBlankInValid: false,
            requiredEmailInValid: false,
            isEmailAvailable: true,
        });
    }

    /**
     * Onchange Input
     */
    onChange() {
        this.setState({
            canClear: this.input.value.length,
            requiredInValid: false,
            requiredBlankInValid: false,
            requiredEmailInValid: false,
            isEmailAvailable: true,
        });
        if (this.props.inputFieldOnChange) {
            this.props.inputFieldOnChange(this.props.Code, this.input.value);
        }
    }

    /**
     * onfocus
     */
    onFocus() {
        this.setState({
            canClear: this.input.value.length,
            requiredInValid: false,
            isEmailAvailable: true,
            showGoogleSuggest: true
        });
    }

    /**
     * OnBlur Input
     */
    onBlur() {
        if (this.input.value.length && CustomerService.validateEmail(this.input.value.trim())) {
            if (this.props.checkEmail)
                this.props.checkEmail(this.input.value);
        }
        if (!DeviceHelper.isAndroid()) {
            this.timeOut = setTimeout(() => {
                this.validate();
                this.setState({
                    canClear: false,
                    showGoogleSuggest: false
                })
            }, 200);
        } else {
            this.timeOut = setTimeout(() => {
                this.validate();
            }, 200);
        }
    }

    /**
     * setEmailUnAvailable
     */
    setEmailUnAvailable() {
        this.setState({
            canClear: false,
            isEmailAvailable: false,
            requiredBlankInValid: false,
            requiredInValid: true,
        })
    }

    /**
     * validate input
     * @returns {boolean}
     */
    validate() {
        let {Required, RequiredEmail,} = this.props;
        let {IsRequired} = this.state;
        Required = (IsRequired !== null && typeof IsRequired !== 'undefined') ? IsRequired : Required;

        let validate = false;
        let validateEmail = false;
        let validateBlank = false;
        if (Required) {
            if (!this.input || this.input.value.length <= 0) {
                validate = true;
                validateBlank = true;
            } else {
                validateBlank = false;
                if (RequiredEmail) {
                    if (CustomerService.validateEmail(this.input.value.trim())) {
                        validate = false;
                        validateEmail = false;
                    } else {
                        validate = true;
                        validateEmail = true;
                        this.setState({
                            canClear: false
                        });
                    }
                }
            }
        }

        this.setState({
            requiredInValid: validate,
            requiredBlankInValid: validateBlank,
            requiredEmailInValid: validateEmail,
        });

        if (!this.state.isEmailAvailable) {
            this.setState({
                canClear: false,
                isEmailAvailable: false,
                requiredBlankInValid: false,
                requiredInValid: true,
            });
            return true;
        }
        return validate;
    }

    /**
     * clear input
     */
    clear() {
        if (this.input) {
            this.input.value = "";
        }

        this.setState({
            canClear: false
        })
    }

    /**
     * set location info
     * @param locationInfo
     */
    setLocationInfo(locationInfo) {
        this.props.setLocationInfo(locationInfo);
    }

    /**
     * get google api key
     * @returns {*}
     */
    getGoogleKey() {
        let config = Config.config;
        if (config) {
            let googleApiKey = config.settings.find(item => item.path === CustomerConstant.GOOGLE_API_PATH).value;
            if (!googleApiKey) {
                return ''
            }
            return googleApiKey
        }
        return '';
    }

    /**
     * @return boolean
     */
    isShowWarningMessage() {
        if(this.props.Code === "telephone" && this.props.isDisabled && this.state.showWarningMessage) {
            return true;
        }

        return false;
    }

    /**
     * @return string
     */
    getWarningMessage() {
        if(this.props.Code === "telephone") {
            return "Customer telephone is the phone in default billing address";
        }

        return "";
    }

    /**
     * Is error
     *
     * @returns {*}
     */
    isError() {
        let {
            requiredInValid, requiredBlankInValid, requiredEmailInValid,
        } = this.state;
        return requiredInValid || requiredBlankInValid || requiredEmailInValid;
    }

    /**
     * Get helper text
     *
     * @returns {string}
     */
    getHelperText() {
        let {
            requiredBlankInValid, requiredEmailInValid, isEmailAvailable
        } = this.state;
        let helperText = "";
        if (requiredBlankInValid) {
            helperText = "This is a required field";
        } else {
            if (requiredEmailInValid) {
                helperText = "Please enter a valid email address";
            }
            if (!isEmailAvailable) {
                helperText = "Email address is existed";
            }
        }
        return helperText;
    }

    /**
     * Get end adornment
     * @returns {JSX.Element|null}
     */
    getEndAdornment() {
        return this.state.canClear ?
            <InputAdornment position="end">
                <IconButton aria-label="remove"
                            onClick={this.clear.bind(this)}
                >
                    <ClearIcon fontSize={"small"}/>
                </IconButton>
            </InputAdornment>
            : null;
    }

    template() {
        let {Label, MaxLength, Code, GoogleSuggest, t} = this.props;
        let {defaultValue, IsRequired} = this.state;
        let googleApiKey = this.getGoogleKey();

        return (
            <Fragment>
                <TextField
                    required={IsRequired}
                    disabled={this.props.isDisabled}
                    fullWidth
                    id={Code}
                    label={t(Label)}
                    autoComplete="off"
                    inputProps={{
                        maxLength: MaxLength
                    }}
                    InputProps={{ // eslint-disable-line
                        endAdornment: this.getEndAdornment(),
                    }}
                    InputLabelProps={{
                        shrink: true,
                    }}
                    defaultValue={defaultValue}
                    error={this.isError()}
                    helperText={t(this.getHelperText())}
                    inputRef={this.setInput.bind(this)}
                    onChange={this.onChange.bind(this)}
                    onBlur={this.onBlur.bind(this)}
                    onFocus={this.onFocus.bind(this)}
                />
                {
                    GoogleSuggest && googleApiKey && this.state.showGoogleSuggest && window.navigator.onLine ?
                        <GoogleSuggestComponent input={this.input ? this.input.value : ""}
                                                open={this.state.showGoogleSuggest}
                                                anchorEl={this.input}
                                                apiKey={googleApiKey}
                                                setLocationInfo={this.setLocationInfo.bind(this)}/>
                        :
                        null
                }
            </Fragment>
        );
    }
}

CustomerInputComponent.propTypes = {
    Code: PropTypes.string,
    Required: PropTypes.bool,
    RequiredEmail: PropTypes.bool,
    Label: PropTypes.string,
    IsOptional: PropTypes.bool,
    DefaultValue: PropTypes.string,
    MaxLength: PropTypes.number,
    OneRow: PropTypes.bool,
    GoogleSuggest: PropTypes.bool,
    setLocationInfo: PropTypes.func,
};

/**
 * CustomerInputComponent
 */
export default ComponentFactory.get(CustomerInputComponent);



