import React, {Fragment} from "react";
import ComponentFactory from '../../../../framework/factory/ComponentFactory';
import CoreContainer from '../../../../framework/container/CoreContainer';
import ContainerFactory from "../../../../framework/factory/ContainerFactory";
import CoreComponent from "../../../../framework/component/CoreComponent";
import OrderService from "../../../../service/sales/OrderService";
import ListItem from '@material-ui/core/ListItem';
import Divider from '@material-ui/core/Divider';
import ListItemSecondaryAction from '@material-ui/core/ListItemSecondaryAction';
import ListItemText from '@material-ui/core/ListItemText';
import Chip from '@material-ui/core/Chip';
import OrderStyle from "../../../style/material-styles/order/OrderStyle";
import {withStyles} from "@material-ui/core";
import OrderHelper from "../../../../helper/OrderHelper";

export class Order extends CoreComponent {
    static className = 'Order';

    /**
     * get price label
     * @returns {{className: string, value: string}}
     */
    getPriceLabel() {
        return OrderService.getPriceLabel(this.props.order);
    }

    /**
     * handle select order
     * @param order
     */
    selectOrder(order) {
        this.props.selectOrder(order);
    }

    /**
     * template
     * @returns {*}
     */
    template() {
        let {order, classes} = this.props;
        let priceLabel = this.getPriceLabel();
        return (
            <Fragment>
                <div onClick={() => this.selectOrder(order)}>
                    <ListItem >
                        <ListItemText
                            primary={order.increment_id}
                            secondary={  <Chip component='span'
                                               className={classes[order.status]} label={
                                this.props.t(OrderService.getDisplayStatus(order.state, order.status))
                            } />}
                        />
                        <ListItemSecondaryAction>
                            <ListItemText className={classes.orderAmountDetail}
                                          primary={OrderHelper.formatPrice(order.grand_total, order)}
                                          secondary={  <span className={classes[priceLabel.className]}>{priceLabel.value}</span>}
                            />
                        </ListItemSecondaryAction>
                    </ListItem>
                    <Divider className={classes.dividerItem} variant="inset" component="li" />
                </div>
            </Fragment>
        );
    }
}

class OrderContainer extends CoreContainer {
    static className = 'OrderContainer';
}

/**
 * @type {Order}
 */
export default ContainerFactory.get(OrderContainer).withRouter(
    withStyles(OrderStyle)(ComponentFactory.get(Order))
);


