import CoreService from "../CoreService";
import ServiceFactory from "../../framework/factory/ServiceFactory"

export class MaterialThemeService extends CoreService{
    static className = 'MaterialThemeService';

    /**
     * Get Theme Options
     *
     * @returns {{palette: {primary: {main: string}}}}
     */
    getThemeOptions() {
        return {
            palette: {
                primary: {
                    main: '#1d63dc',
                },
                action: {
                    disabledBackground: 'gray',
                    disabled: 'white'
                }
            },
        };
    }
}

/**
 * @type {MaterialThemeService}
 */
let materialThemeService = ServiceFactory.get(MaterialThemeService);

export default materialThemeService;


