import React, {Fragment} from 'react'
import CoreComponent from "../../../framework/component/CoreComponent";
import PosService from "../../../service/PosService";
import LocationService from "../../../service/LocationService";
import UserService from "../../../service/user/UserService";
import CheckoutAction from "../../action/CheckoutAction";
import CoreContainer from "../../../framework/container/CoreContainer";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import {bindActionCreators} from "redux";
import MenuAction from "../../action/MenuAction";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import permission from "../../../helper/Permission";
import PaymentHelper from "../../../helper/PaymentHelper";
import SessionHelper from "../../../helper/SessionHelper";
import SessionAction from "../../action/SessionAction";
import ConfigHelper from "../../../helper/ConfigHelper";
import {
    Avatar, Box, Divider,
    Drawer,
    IconButton,
    List,
    ListItem,
    ListItemIcon,
    ListItemText, Typography,
    withStyles
} from "@material-ui/core";
import {Menu} from "@material-ui/icons";
import layout from "../../../framework/Layout";
import Logout from "../logout/Logout";
import MenuStyles from "../../style/material-styles/menu/Menu";
import CheckoutIconImage from "../../style/images/checkout.svg";
import LogoutIconImage from "../../style/images/logout.svg";

export class MenuComponent extends CoreComponent {
    static className = 'MenuComponent';

    /**
     *   initial state
     *   get staff, location, pos information
     */
    constructor() {
        super();
        this.state = {
            staffName: UserService.getStaffName(),
            locationName: LocationService.getCurrentLocationName(),
            PosName: PosService.getCurrentPosName().replace(/ *\([^)]*\) */g, ""),
        };
    }

    /**
     *  close menu, call action whenever user click some menu item
     *
     * @param {Object} item
     * @return void
     */
    changeRoute(item) {
        if (this.props.history.location.pathname.indexOf(item.path) !== -1) {
            return this;
        }

        this.toggle();

        // if (SessionService.needDirectSession() && item.id !== 'settings') {
        //     this.props.actions.redirectToManageSession();
        //     this.props.history.replace('/session');
        //
        // } else {
            if (item.path) {
                this.props.history.replace(item.path);
            }
        // }
    }

    /**
     *  toggle action menu button
     *  @return void
     */
    toggle() {
        this.props.actions.toggle()
    }

    /**
     *  logout button DOM expression
     *  @return string
     *
     * */
    logoutButton() {
        return (
            <ListItem button key={'item-logout'}
                      onClick={() => this.onClickLogout()}
            >
                <ListItemIcon>
                    <Avatar src={LogoutIconImage} variant="square" className={this.props.classes.menuItemIcon}/>
                </ListItemIcon>
                <ListItemText primary={this.props.t('Logout')} />
            </ListItem>
        )
    }

    /**
     * Toggle Menu Button
     *
     * @returns {JSX.Element}
     */
    toggleMenuButton() {
        return (
            <IconButton
                className={this.props.classes.toggleMenuButton}
                top={0}
                left={0}
                onClick={() => this.toggle()}
            >
                <Menu fontSize={'large'}/>
            </IconButton>
        )
    }

    /**
     * onclick logout
     */
    onClickLogout() {
        this.toggle();
        this.props.actions.clickLogoutItem();
    }

    /**
     *  menu item DOM expression
     *  validate permission
     *
     *  @return string
     *
     * */
    getMenuItems() {
        let menuItems = this.props.items.map(item => {
            if (item.component.acl && !permission.isAllowed(item.component.acl)) {
                return '';
            }

            if (item.id === 'session') {
                if (!SessionHelper.isEnableSession()) {
                    if(!item.className.split(' ').includes('hidden')) {
                        item.className += ' hidden';
                    }
                }
            }
            let icon = CheckoutIconImage;
            if (item.icon) {
                icon = item.icon;
            }

            return (
                <ListItem button key={item.id}
                          onClick={() => this.changeRoute(item)}
                          selected={this.props.history.location.pathname.indexOf(item.path) !== -1}
                >
                    <ListItemIcon>
                        <Avatar src={icon} variant="square" className={this.props.classes.menuItemIcon}/>
                    </ListItemIcon>
                    <ListItemText primary={this.props.t(item.title)} />
                </ListItem>
            );
        });
        menuItems.push(this.logoutButton());
        return menuItems;
    }

    clickBackButton() {
        return;
    }

    getPosVersion() {
      return ConfigHelper.getConfig('about/product/line')
          + ' ' + ConfigHelper.getConfig('about/product/version')
    }

    canBackToCatalog() {
        const {currentPage, hasPaidOrWaitingGatewayPayment} = this.props;
        return (
            [].indexOf(currentPage) !== -1
            && !hasPaidOrWaitingGatewayPayment
        );
    }

    canUseMenuToggle() {
        const {currentPage} = this.props;
        return [].indexOf(currentPage) === -1;
    }

    /**
     *  component render DOM expression
     *  @return string
     *
     */
    template() {
        const {isOpen, classes} = this.props;
        return (
            <Fragment>
                <Drawer anchor={'left'}
                        open={isOpen}
                        className={classes.drawer}
                        classes={{
                            paper: classes.drawerPaper,
                        }}
                        onClose={() => this.toggle()}
                >
                    <Box className={classes.menuTitle}>
                        <Typography variant="body1" className={classes.staffName}
                                    paragraph>{this.state.staffName}</Typography>
                        <Typography variant="body2" paragraph>{this.state.PosName} / {this.state.locationName}</Typography>
                    </Box>
                    {layout('menu')('menu_layout')('menu_title')()(this,this.state)}
                    <Divider />
                    <List className={classes.list}>
                        {this.getMenuItems()}
                    </List>
                    <Divider />
                    <Box className={classes.menuFooter}>
                        <Typography
                            className={classes.posVersion}
                            variant="body1" paragraph>{this.getPosVersion()}</Typography>
                    </Box>
                </Drawer>
                <Logout/>
            </Fragment>
        );
    }
}

/**
 *
 * @type {MenuComponent}
 */
const component = withStyles(MenuStyles)(ComponentFactory.get(MenuComponent));

export class MenuContainer extends CoreContainer {
    static className = 'MenuContainer';

    /**
     *  map state to props of component
     *
     * @param {Object} state
     * @return {{active, items}}
     */
    static mapState(state) {
        const {items, isOpen} = state.core.menu;
        const {currentPage} = state.core.checkout.index;
        const {quote} = state.core.checkout;
        let hasPaidOrWaitingGatewayPayment = PaymentHelper.hasPaidOrWaitingGatewayPayment(quote.payments);

        return {
            isOpen,
            items,
            currentPage,
            hasPaidOrWaitingGatewayPayment
        }
    }

    /**
     *  map dispatch to props of component
     *
     * @param dispatch
     * @return {{actions: {CLICK_MENU_ITEM: string, CLICK_LOGOUT_ITEM: string, clickMenuItem: function(*), clickLogoutItem: function()}|ActionCreator<any>|ActionCreatorsMapObject}}
     */
    static mapDispatch(dispatch) {
        let props = {
            actions: bindActionCreators({...MenuAction, ...CheckoutAction}, dispatch)
        };
        props.actions.redirectToManageSession = () => dispatch(SessionAction.redirectToManageSession());
        return props;
    }
}

/**
 *
 * @type {MenuContainer}
 */
const container = ContainerFactory.get(MenuContainer);

export default container.withRouter(component)



