import React, {Fragment} from 'react';
import CoreComponent from "../../../framework/component/CoreComponent";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import {Button, Typography, withStyles} from "@material-ui/core";
import {PermIdentity} from "@material-ui/icons";
import CustomerButtonStyle from "../../style/material-styles/customer/CustomerButtonStyle";
import CustomerList from "./CustomerList";
import CustomerAction from "../../action/CustomerAction";

export class CustomerButtonComponent extends CoreComponent {
    static className = 'CustomerButtonComponent';

    /**
     * Get current customer name
     *
     * @return {string}
     */
    getCustomerName() {
        let customer = this.props.quote.customer;
        if (customer && customer.id) {
            return customer.firstname + " " + customer.lastname;
        }
        return this.props.t('Guest');
    }

    /**
     * Open customer list
     */
    openCustomerList() {
        this.props.actions.showCustomerList();
    }

    /**
     * render template
     *
     * @returns {*}
     */
    template() {
        return (
            <Fragment>
                <Button variant="outlined"
                        color={'inherit'}
                        className={this.props.classes.customerButton}
                        endIcon={<PermIdentity />}
                        onClick={() => this.openCustomerList()}
                >
                    <Typography noWrap>{this.getCustomerName()}</Typography>
                </Button>
                {
                    this.props.showCustomerList ?
                        <CustomerList />
                        : null
                }
            </Fragment>
        );
    }
}

/**
 *
 * @type {CustomerButtonComponent}
 */
const component = withStyles(CustomerButtonStyle)(ComponentFactory.get(CustomerButtonComponent));

export class CustomerButtonContainer extends CoreContainer{
    static className = 'CustomerButtonContainer';

    /**
     * @inheritDoc
     */
    static mapState(state) {
        let quote = state.core.checkout.quote;
        let {showCustomerList} = state.core.customer.customerList;
        return {
            quote,
            showCustomerList
        };
    }

    /**
     * @inheritDoc
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                showCustomerList: () => dispatch(CustomerAction.showCustomerList()),
            }
        }
    }
}

/**
 *
 * @type {CustomerButtonContainer}
 */
const container = ContainerFactory.get(CustomerButtonContainer);
export default container.getConnect(component);



