import React, {Fragment} from 'react';
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import {CoreComponent} from "../../../framework/component";
import UserAction from "../../action/UserAction";
import UserService from "../../../service/user/UserService";
import Logo from "../../style/images/logo.png"
import i18n from "../../../config/i18n";
import {toast} from "react-toastify";
import SignoutAction from "../../action/SignoutAction";
import SharingAccountPopup from "./SharingAccountPopup";
import ScanAction from "../../action/ScanAction";
import ScanConstant from "../../constant/ScanConstant";
import {
    Avatar,
    Button,
    Container,
    Dialog, DialogActions, DialogContent, DialogContentText,
    DialogTitle, InputAdornment, Link,
    TextField,
    Typography, withStyles
} from "@material-ui/core";
import LoginStyles from '../../style/material-styles/user/Login';
import {AccountCircle, Lock} from "@material-ui/icons";

export class Login extends CoreComponent {
    static className = 'Login';

    /**
     * constructor
     *
     * @param props
     */
    constructor(props) {
        super(props);
        let logoUrl = UserService.getLocalLogo();
        if (!logoUrl) {
            this.props.getLogo();
        }
        this.state = {
            active: false,
            loginTitle: this.props.t('login'),
            error: '',
            modalTitle: '',
            modalContent: '',
            logoUrl: logoUrl,
            showSharingPopUp: false
        };
    }

    /**
     * component will mount
     */
    componentWillMount() {
        const session = UserService.getSession();
        const sharingAccount = UserService.getSharingAccount();
        if (session) {
            if(sharingAccount.toString() === '1'){
                return this.props.history.push('/locations');
            }else{
                this.setState({showSharingPopUp : true,
                        loginTitle: this.props.t('login')
                });
            }
        }
        this.props.setScanPage(ScanConstant.SCAN_PAGES.LOGIN);
    }

    /**
     * component will mount
     */
    componentWillReceiveProps(nextProps) {

        if(this.state.isOpenModal) {
            this.setState({
                isOpenModal: false
            });
        }
        if(this.state.clickedLogin) {
            this.setState({
                clickedLogin: false
            });
        }
        if(!nextProps.user.connection) {
            this.showInternetWarning();
        }
        if (nextProps.user.error) {
            this.showInvalidAccountMessage(nextProps.user.error);
        }
        if(nextProps.user.logoUrl !== undefined) {
            this.setLogoUrl(nextProps.user.logoUrl);
        }
        if(nextProps.signout !== undefined &&
           nextProps.signout.message) {
            this.props.forceSignOutSuccess();
            toast.error(
                i18n.translator.translate(nextProps.signout.message),
                {
                    className: 'wrapper-messages messages-warning',
                    autoClose: 5000
                }
            );
        }

        /* not sharing account && has occupy pos */
        if(nextProps.user.sharing) {
            if (nextProps.user.sharing.sharing_account.toString() !== '1' ) {
                this.setState({
                    showSharingPopUp: true,
                    loginTitle: this.props.t('login')
                });
            }
        }

        if (nextProps.user.after_sharing && nextProps.user.after_sharing === true){
            this.setState({
                showSharingPopUp: false
            });
            this.props.afterContinueLogin(false);
        }
    }

    /**
     * component will update
     *
     * @param nextProps
     */
    componentWillUpdate(nextProps) {
        if (nextProps.user.session) {
            /* not sharing account && has occupy pos */
            if(nextProps.user.sharing.sharing_account.toString() !== '1'){
                return this;
            }
            /* sharing account || (not sharing but occupy pos ) */
            if(this.state.showSharingPopUp === false) {
                return this.props.history.push({
                    pathname: '/locations',
                    state: {}
                });
            }
        }
    }

    /**
     * check active login button
     */
    checkActiveLogin() {
        if (this.usernameRef.value && this.passwordRef.value) {
            this.setState({active: true});
        } else {
            this.setState({active: false});
        }
    }

    /**
     * reset password after onclick
     */
    resetPassword() {
        if(this.state.resetPassword) {
            this.passwordRef.value = '';
            this.setState({active: false});
            this.setState({resetPassword: false});
        }
    }

    /**
     * set state reset password after click to other place
     */
    checkResetPassword() {
        this.setState({resetPassword: true});
    }


    /**
     * focus password field after press enter button from username
     */
    handleUserKeyPress(e) {
        if (e.key === 'Enter') {
            this.passwordRef.focus();
        }
    }

    /**
     * login after press enter button
     */
    handlePasswordKeyPress(e) {
        this.passwordRef.focus();
        if (e.key === 'Enter' && this.state.active) {
            this.login();
        }
    }

    /**
     * open internet warning popup
     */
    showInternetWarning() {
        let title = this.props.t('Network Error');
        let content = this.props.t('You must connect to a Wi-Fi or cellular data network to access the POS');
        this.setState({
            isOpenModal: true,
            modalTitle: title,
            modalContent: content
        });
    }

    /**
     * open invalid account popup
     * @param message
     */
    showInvalidAccountMessage(message) {
        this.setState({
            loginTitle: this.props.t('login'),
            isOpenModal: true,
            modalTitle: this.props.t('Error'),
            modalContent: message
        });
    }

    /**
     * set logo url
     * @param logoUrl
     */
    setLogoUrl(logoUrl) {
        let url = Logo;
        if(logoUrl) {
            url = logoUrl;
        }
        UserService.saveLocalLogo(url);
        this.setState({
            logoUrl: url
        });
    }

    /**
     * login handle
     */
    login() {
        if(this.state.clickedLogin) {
            return;
        }
        if(this.props.user.connection) {
            this.setState({
                loginTitle: this.props.t('please wait') + '...',
                clickedLogin: true
            });
            this.props.clickLogin(this.usernameRef.value, this.passwordRef.value);
        } else {
            this.showInternetWarning();
        }
    }

    /**
     * confirm modal
     */
    confirm() {
        if(!this.props.user.connection) {
            this.setState({isOpenModal: false});
        } else {
            this.props.closePopup();
        }
    }

    /**
     *
     */
    handleShowSharingPopup(){
       this.setState({
           showSharingPopUp: false,
           loginTitle: this.props.t('login')
       });
    }

    /**
     * render login form
     *
     */
    template() {
        let {classes} = this.props;
        if (this.state.showSharingPopUp) {
            return <SharingAccountPopup sharingPopupBehavious={() => this.handleShowSharingPopup()}/>;
        }
        return (
            <Fragment>
                <Container component="main" maxWidth="xs">
                    <div className={classes.wrapperLogin}>
                        <Avatar src={this.state.logoUrl} variant="square" className={classes.logo}/>
                        <Typography component="h1" variant="h5">{this.props.t('Login')}</Typography>
                        <form className={classes.form} noValidate>
                            <TextField
                                margin="normal"
                                required
                                fullWidth
                                id="username"
                                label={this.props.t('Username')}
                                name="username"
                                autoComplete="off"
                                autoFocus
                                inputRef={(c) => {this.usernameRef = c;}}
                                InputProps={{
                                    startAdornment: (
                                        <InputAdornment position="start">
                                            <AccountCircle />
                                        </InputAdornment>
                                    ),
                                }}
                                onChange={() => this.checkActiveLogin()}
                                onKeyPress={(e) => this.handleUserKeyPress(e)}
                            />
                            <TextField
                                margin="normal"
                                required
                                fullWidth
                                name="password"
                                label={this.props.t('Password')}
                                type="password"
                                id="password"
                                autoComplete="off"
                                inputRef={(c) => {this.passwordRef = c;}}
                                InputProps={{
                                    startAdornment: (
                                        <InputAdornment position="start">
                                            <Lock />
                                        </InputAdornment>
                                    ),
                                }}
                                onChange={() => this.checkActiveLogin()}
                                onClick={() => this.resetPassword()}
                                onBlur={() => this.checkResetPassword()}
                                onKeyPress={(e) => this.handlePasswordKeyPress(e)}
                            />
                            <Button
                                type="button"
                                fullWidth
                                variant="contained"
                                color="primary"
                                size='large'
                                disabled={!this.state.active}
                                className={classes.submit}
                                ref={(c) => {this.loginButton = c;}}
                                onClick={() => this.login()}
                            >
                                {this.state.loginTitle}
                            </Button>
                        </form>
                        <Typography className={classes.poweredByTitle}>
                            {this.props.t("Powered by") + " "}
                            <Link color="inherit"
                               href="https://www.magestore.com">
                                Magestore
                            </Link>
                            .
                        </Typography>
                    </div>
                </Container>
                <Dialog maxWidth="xs"
                        aria-labelledby="dialog-title"
                        open={!!this.state.isOpenModal}
                >
                    <DialogTitle id="dialog-title">{this.state.modalTitle}</DialogTitle>
                    <DialogContent>
                        <DialogContentText id="dialog-description">
                            {this.props.t(this.state.modalContent)}
                        </DialogContentText>
                    </DialogContent>
                    <DialogActions>
                        <Button onClick={() => this.confirm()} color="primary" autoFocus>
                            {this.props.t('OK')}
                        </Button>
                    </DialogActions>
                </Dialog>
            </Fragment>
        );
    }
}

export class LoginContainer extends CoreContainer {
    static className = 'LoginContainer';
    /**
     * Map states
     *
     * @param state
     * @returns {{user: {connection, error, logoUrl: *|string}}}
     */
    static mapState(state) {
        const {user, signout} = state.core;
        let connection = state.core.internet.connection;
        let error = user.error;
        let logoUrl = user.logoUrl;
        if(!connection) {
            error = '';
        }
        let userProps = {...user, connection: connection, error: error, logoUrl: logoUrl};
        return {user: userProps, signout};
    }

    /**
     * Map actions
     *
     * @param dispatch
     * @returns {{clickLogin: function(*=, *=): *, closePopup: function(): *, getLogo: function(): *, forceSignOutSuccess: function(): *}}
     */
    static mapDispatch(dispatch) {
        return {
            clickLogin: (username, password) => dispatch(UserAction.clickLogin(username, password)),
            closePopup: () => dispatch(UserAction.closePopup()),
            getLogo: () => dispatch(UserAction.getLogo()),
            forceSignOutSuccess: () => dispatch(SignoutAction.forceSignOutSuccess()),
            afterContinueLogin : (string) => dispatch(UserAction.afterContinueLogin(string)),
            setScanPage: scanPage => dispatch(ScanAction.setScanPage(scanPage))
        }
    }
}

export default ContainerFactory.get(LoginContainer).withRouter(
    withStyles(LoginStyles)(ComponentFactory.get(Login))
)



