import {fire} from "../../../../event-bus";

const styles = theme => {
    let style = {
        list: {
            width: '100%',
            backgroundColor: theme.palette.background.paper,
            height: 'inherit',
            overflowY: 'auto'
        },
        searchForm: {
            width: '100%'
        },
        root: {
            width: '100%',
            backgroundColor: theme.palette.background.paper
        },
        listHeader: {
            backgroundColor: '#ced0d6',
            textAlign: 'center'
        }
    };
    fire('material_styles_order_order_list_style', {theme, style});
    return style;
};

export default styles;



