import React, {Fragment} from 'react';
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import {
    AppBar,
    Box, Button, CircularProgress,
    Container,
    Dialog,
    Fade,
    IconButton,
    List,
    Toolbar,
    Typography,
    withStyles
} from "@material-ui/core";
import CustomerListStyle from "../../style/material-styles/customer/CustomerListStyle";
import CustomerAction from "../../action/CustomerAction";
import AbstractList from "../../../framework/component/list/AbstractList";
import ConfigHelper from "../../../helper/ConfigHelper";
import PerformanceService from "../../../service/performance/PerformanceService";
import PerformanceConstant from "../../../service/performance/PerformanceConstant";
import QueryService from "../../../service/QueryService";
import Customer from "./customer-list/Customer";
import {ArrowBack, PermIdentity, Edit as EditIcon} from "@material-ui/icons";
import punycode from "punycode";
import FormControl from "@material-ui/core/FormControl";
import Input from "@material-ui/core/Input";
import InputAdornment from "@material-ui/core/InputAdornment";
import Search from "@material-ui/icons/Search";
import QuoteAction from "../../../view/action/checkout/QuoteAction";
import AddNewCustomerButton from "./AddNewCustomerButton";
import CustomerPopup from "./CustomerPopup";

export class CustomerListComponent extends AbstractList {
    static className = 'CustomerListComponent';

    setCustomerListElement = element => this.customer_list = element;
    setSearchBoxElement = element => this.search_box = element;

    /**
     * Constructor
     *
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {
            items: [],
            search_box_value: ''
        }
    }

    /**
     * @inheritDoc
     */
    componentDidMount() {
        if (this.props.showCustomerList) {
            /* Load customer when open popup customer list */
            this.clearItems();
            this.searchCustomer(this.state.search_box_value);
            this.startLoading();
        }
    }

    /**
     * This function after mapStateToProps then push more items to component or change load customer mode
     *
     * @param nextProps
     */
    componentWillReceiveProps(nextProps) {
        if (nextProps.customers && nextProps.search_key === this.state.search_box_value) {
            this.addItems(nextProps.customers);
            this.stopLoading();
            if (nextProps.total_count > nextProps.customers.length) {
                let self = this;
                setTimeout(() => {
                    if (
                        self.props.total_count > self.props.customers.length &&
                        self.customer_list &&
                        self.customer_list.scrollHeight > 0 &&
                        self.customer_list.clientHeight > 0 &&
                        self.customer_list.scrollHeight <= self.customer_list.clientHeight
                    ) {
                        self.lazyload();
                    }
                }, 300);
            }
        }
        if (nextProps.updated_customers && nextProps.updated_customers.length && this.state.items.length) {
            this.updateListAfterSyncCustomer(nextProps.updated_customers);
        }
        if (nextProps.deleted_customer_ids && nextProps.deleted_customer_ids.length && this.state.items.length) {
            this.updateListAfterSyncDeletedCustomers(nextProps.deleted_customer_ids);
        }
    }

    /**
     * update list customer after sync customer
     * @param customers
     */
    updateListAfterSyncCustomer(customers = []) {
        if (customers && customers.length) {
            let items = this.state.items;

            customers.map(customer => {
                let index = items.findIndex(item => item.id === customer.id);
                if (index >= 0) {
                    items[index] = customer;
                }
                return customer;
            });
            this.addItems(items);
            this.props.actions.resetSyncActionUpdateCustomer();
        }
    }

    /**
     * update list customer after sync deleted customer
     * @param ids
     */
    updateListAfterSyncDeletedCustomers(ids = []) {
        if (ids && ids.length) {
            let items = this.state.items;
            ids.map(id => {
                let index = items.findIndex(item => item.id === id);
                if (index >= 0) {
                    items.splice(index, 1);
                }
                return id;
            });
            this.addItems(items);

            this.props.actions.resetSyncDeletedCustomers();
        }
    }

    /**
     * Load more customer when you scroll customer list
     */
    lazyload() {
        if (this.canLoad() === true) {
            this.startLoading();
            this.searchCustomer(
                this.state.search_box_value,
                this.props.search_criteria.page_size,
                this.props.search_criteria.current_page + 1
            );
        }
    }

    /**
     * On Scroll list
     * @param event
     */
    onScrollList(event) {
        let scrollTop = event.target.scrollTop;
        let maxScrollTop = event.target.scrollHeight - event.target.clientHeight;
        if (maxScrollTop < (scrollTop + 100)) {
            this.lazyload();
        }
    }

    /**
     * Check can load more customer
     *
     * @return {boolean}
     */
    canLoad() {
        return !this.isLoading() && (this.props.customers.length < this.props.total_count);
    }

    /**
     * Change search box input value
     *
     * @param event
     */
    changeSearchKey(event) {
        let searchKey = event.target.value.trim();
        if (searchKey.length && ConfigHelper.regexEmail.test(searchKey)) {
            searchKey = punycode.toASCII(searchKey);
        }
        this.setState({search_box_value: searchKey});
        if (this.searchTimeOut) {
            clearTimeout(this.searchTimeOut);
        }
        this.searchTimeOut = setTimeout(() => {
            this.props.actions.resetCustomerList();
            this.clearItems();
            this.startLoading();
            this.searchCustomer(searchKey);
        }, 800);
    }

    /**
     * Clear search box
     */
    clearSearchBox() {
        this.search_box.value = "";
        this.setState({search_box_value: ""});
        this.clearItems();
        this.startLoading();
        this.searchCustomer();
    }

    /**
     * Search Customer
     *
     * @param searchKey
     * @param pageSize
     * @param currentPage
     */
    searchCustomer(searchKey = '', pageSize = 10, currentPage = 1) {
        PerformanceService.startMeasure(PerformanceConstant.SEARCH_CUSTOMER);
        let queryService = QueryService.reset();
        queryService.setOrder('full_name').setPageSize(pageSize).setCurrentPage(currentPage);
        queryService.addQueryString(searchKey);
        this.props.actions.searchCustomer(queryService, searchKey);
    }

    /**
     * Close
     */
    close() {
        this.props.actions.closeCustomerList();
    }

    /**
     * Check product list items is empty and is not loading products
     *
     * @return {boolean}
     */
    isEmptyItem() {
        return this.state.items.length <= 0 && !this.isLoading();
    }

    /**
     * Get current quote customer name
     *
     * @return {string}
     */
    getQuoteCustomerName() {
        let customer = this.props.quote.customer;
        if (customer && customer.id) {
            return customer.firstname + " " + customer.lastname;
        }
        return this.props.t('Guest');
    }

    /**
     * Select customer
     *
     * @param customer
     */
    selectCustomer(customer) {
        this.props.actions.setCustomer(customer);
        this.close();
    }

    /**
     * Handle click edit customer
     */
    handleClickEditCustomer() {
        if (this.props.quote.customer) {
            this.props.actions.openCustomerPopup(this.props.quote.customer);
        }
    }

    /**
     * render template
     *
     * @returns {*}
     */
    template() {
        let {classes, showCustomerList, t, showCustomerPopup} = this.props;
        return (
            <Fragment>
                <Dialog fullScreen open={showCustomerList} onClose={() => this.close()}>
                    <AppBar>
                        <Toolbar>
                            <IconButton edge="start"
                                        onClick={() => this.close()}
                                        className={classes.backButton} color="inherit" aria-label="menu">
                                <ArrowBack />
                            </IconButton>
                            <Typography variant="h6" component="div">
                                {t('CUSTOMER')}
                            </Typography>
                            <AddNewCustomerButton />
                        </Toolbar>
                    </AppBar>
                    <Toolbar />
                    <Toolbar>
                        <IconButton edge="start" disableRipple disableFocusRipple disableTouchRipple>
                            <PermIdentity />
                        </IconButton>
                        <Typography variant="h6" component="div">
                            {this.getQuoteCustomerName()}
                        </Typography>
                        {
                            this.props.quote.customer ?
                                <IconButton edge="end" onClick={() => this.handleClickEditCustomer()}>
                                    <EditIcon />
                                </IconButton>
                                : null
                        }
                    </Toolbar>
                    <Toolbar>
                        <FormControl variant="standard" className={classes.searchForm}>
                            <Input
                                id="input-with-icon-textfield"
                                className="input-search form-control customer-input-search"
                                onKeyUp={event => this.changeSearchKey(event)}
                                startAdornment={<InputAdornment position="start"><Search /></InputAdornment>}
                                inputProps={{
                                    'aria-label': 'weight',
                                }}
                                inputRef={this.setSearchBoxElement}
                                placeholder={t('Search by name or contact information')}
                            />
                        </FormControl>
                    </Toolbar>
                    <Box className={classes.list}
                         ref={this.setCustomerListElement}
                         onScroll={(event) => this.onScrollList(event)}>
                        {
                            this.isEmptyItem() ?
                                <Typography variant="h6" component="div" align='center'>
                                    {this.props.t('We couldn\'t find any records.')}
                                </Typography>
                                :
                                <List className={classes.root}>
                                    {
                                        this.state.items.map((customer) => {
                                            return (
                                                <Customer key={customer.email + customer.updated_at}
                                                          customer={customer}
                                                          selectCustomer={(customer) => this.selectCustomer(customer)}
                                                />
                                            );
                                        })
                                    }
                                </List>
                        }
                        <Container align='center'>
                            <Fade
                                in={this.isLoading()}
                                unmountOnExit
                            >
                                <CircularProgress />
                            </Fade>
                        </Container>
                    </Box>
                    {
                        this.props.quote.customer ?
                            <Button variant={'contained'}
                                    onClick={() => this.selectCustomer()}
                                    size={'large'}
                                    className={classes.removeCustomerButton}
                            >
                                {t('Remove Customer')}
                            </Button>
                            : null
                    }
                </Dialog>
                {
                    showCustomerPopup ?
                        <CustomerPopup />
                        : null
                }
            </Fragment>
        );
    }
}

/**
 *
 * @type {CustomerListComponent}
 */
const component = withStyles(CustomerListStyle)(ComponentFactory.get(CustomerListComponent));

export class CustomerListContainer extends CoreContainer{
    static className = 'CustomerListContainer';

    /**
     * @inheritDoc
     */
    static mapState(state) {
        let {
            customers,
            search_criteria,
            total_count,
            search_key,
            showCustomerList,
            updated_customers,
            deleted_customer_ids
        } = state.core.customer.customerList;
        let {showCustomerPopup} = state.core.customer.customerPopup;
        let quote = state.core.checkout.quote;
        return {
            customers,
            search_criteria,
            total_count,
            search_key,
            showCustomerList,
            updated_customers,
            deleted_customer_ids,
            quote,
            showCustomerPopup
        };
    }

    /**
     * @inheritDoc
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                searchCustomer: (queryService, searchKey) =>
                    dispatch(CustomerAction.searchCustomer(queryService, searchKey)),
                resetCustomerList: () => dispatch(CustomerAction.resetCustomerList()),
                closeCustomerList: () => dispatch(CustomerAction.closeCustomerList()),
                resetSyncActionUpdateCustomer: () => dispatch(CustomerAction.syncActionUpdateDataFinish()),
                resetSyncDeletedCustomers: () => dispatch(CustomerAction.syncDeletedCustomerFinish()),
                openCustomerPopup: (customer) => dispatch(CustomerAction.openCustomerPopup(customer)),
                setCustomer: customer => dispatch(QuoteAction.setCustomer(customer)),
            }
        }
    }
}

/**
 *
 * @type {CustomerListContainer}
 */
const container = ContainerFactory.get(CustomerListContainer);
export default container.getConnect(component);



